quests[27562] = { id = 27562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beezil's Cog", sourceObjective = "It looks like Beezil has already made himself comfortable, and has stuffed several peculiar gizmos into the caravan.\n\nMost of them seem too impractical or dangerous to take with you.  One small cogwheel, however, looks to be fairly well-crafted.", sourceObjectiveStatus = "unverified-source-field" }
quests[27564] = { id = 27564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the Redoubt", description = "Calen sent word - the Twilight are within the redoubt!\n\nIf there will ever be a time when you can earn his favor, this is it!", sourceObjective = "Speak to Calen in the Vermillion Redoubt.", completion = "I hope you're as tough as your gear suggests. The Twilight's Hammer have made their way within the redoubt somehow and I need someone to hunt them down.", sourceObjectiveStatus = "unverified-source-field" }
quests[27565] = { id = 27565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "We've managed to infiltrate the Dark Iron Prison!\n\nWell...we may have, anyway.\n\nKevin Dawson had the...honor...of seeing what was going on over there, and we haven't heard back from him since. You look like the type that doesn't like to die, you should go see if he's ok!\n\nHe's supposed to be inside the hall on the south end of the cavern ahead...though something tells me he may not have made it quite that far.", sourceObjective = "Find Kevin Dawson.", completion = "I don't know how I'm still alive. The patrols keep walking past me like I'm not even here.\n\n...Am I dead, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27567] = { id = 27567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "This is a little hard to believe, but there are Twilight's Hammer members here in Blackrock Depths! I don't know how many there are crawling throughout this place, but I did hear that their lead interrogator, Gerstahn, is in this hallway.\n\nI don't know what they're here torturing for, but maybe you can find out by confronting Gerstahn?", sourceObjective = "\"Interrogate\" High Interrogator Gerstahn.", progress = "Go! Go! Go!", completion = "I see...she did not cooperate. Hopefully we can still stop them before something else terrible happens.", sourceObjectiveStatus = "unverified-source-field" }
quests[27568] = { id = 27568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "Can ye keep a secret? I have a secret tae share with ye if ye can.\n\nEverybody here is CRAZY!!!\n\nThere's goblins over there, Dark Irons right over there, and a giant living fire thing right past this gate! An' that's just what I see in this little cave!\n\nAnd ye! What're ye doin' here!?\n\nOh, I see. Winky sent ye, did he? Sent ye tae talk t' Prospector Seymour, past this gate and t' the right, did he? Well go! Oralius doesn't even care!\n\n...I'll GET YOU FOR THIS WINKY!!!\n\n<Oralius begins to sob.>", sourceObjective = "Speak to Prospector Seymour.", completion = "I would stay away from Oralius. Far, far, far away. He isn't quite right in the head.\n\nNow, let's get onto business!", sourceObjectiveStatus = "unverified-source-field" }
quests[27569] = { id = 27569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Tacticians", description = "General Angerforge and Golem Lord Argelmach lead the Dark Iron armies and their golems against us. If we are to overcome them, the two must be slain.\n\nGo through this door and unlock The Shadowforge Lock, which separates the East and West Garrisons. Then, follow the stairs and keep to the left at the top until you reach the West Garrison. It is there you will find the General and Golem Lord.\n\nKeep your wits about you, they are both well-seasoned combatants. Find Mayara Brightwing should you succeed.", sourceObjective = "Kill General Angerforge and Golem Lord Argelmach.", completion = "I'm sure you are up to the task I have for you if you've made it this far in one piece.\n\n<Mayara Brightwing lowers her voice to a whisper.>\n\nBetween you and me, you may want to enjoy yourself in the Grim Guzzler while you're there. It could be the last drink you ever have.", sourceObjectiveStatus = "unverified-source-field" }
quests[27571] = { id = 27571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Some say that the Grim Guzzler is the secret to the Dark Iron war effort. Their warriors recharge there and emerge thirsty for another innocent soul. I think we can seriously hinder them by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Orfus when you're done.", sourceObjective = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", completion = "The Dark Irons took our Thunderbrew. I'll never let them live after that. I'd kill 'em all myself if I could!\n\nHowever, look ahead and you'll see we have slightly more dire matters to attend to at the moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27573] = { id = 27573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Ahead is the creature known only as Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them, so that this nation may perhaps one day be redeemed.", sourceObjective = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27574] = { id = 27574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Never Forget a Face", description = "You have discovered a partially digested head. Lord Godfrey perks up when he sees it. Perhaps you should give it to him.", sourceObjective = "Give the Partially Digested Head to Lord Godfrey in Silverpine Forest.", progress = "I never forget a face!", completion = "I know that face, {name}. This head belongs to a former Gilnean known as Sean Dempsey. He was imprisoned with Crowley before the great outbreak.\n\n\n\nI wonder if it would be possible to put him back together. The rest of him must be in the belly of these crocolisks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27575] = { id = 27575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Belly of the Beast", description = "I think we can rebuild him. Perhaps if we put him back together he can give us information about Crowley.\n\nWe must kill every crocolisk in this marsh until we find the rest of Sean Dempsey's body! From the belly of the beast this man will be reborn!", sourceObjective = "Recover Dempsey's Torso, Dempsey's Appendages and Dempsey's Giblets.", progress = "At the very least we'll have some crocolisk hides to make fancy shoes out of.", completion = "Now let's see if I can do this.\n\n<Godfrey starts mumbling under his breath.>\n\n...leg bone connects to the thigh bone...\n\n...arm bone to torso...\n\n...sprinkle on a little Forsaken necromancy...\n\nTA-DA!", sourceObjectiveStatus = "unverified-source-field" }
quests[27576] = { id = 27576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwork Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Patch in Dragonmaw Pass, in the canyon below us to the south.", sourceObjective = "Speak to Patch in Dragowmaw Pass.", completion = "You got the dragons in the game! Good on you.\n\nWe'd already laid out plans for our ambush by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nIt's not too late for you to join in on the fun though. We saved some for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27577] = { id = 27577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7th Legion Battle Plans", description = "While destroying Pyrewood will certainly garner us an advantage over the Alliance upon the field of battle, our true purpose here is to leave them crippled.\n\nSouthwest of here, near the Greymane Wall, lies the 7th Legion Base Camp. We must search the base camp for battle plans. With the 7th Legion battle plans we will be able to pinpoint all Alliance troop advancement in Silverpine Forest.", sourceObjective = "Recover the 7th Legion Battle Plan.", progress = "Search every filthy dwarven corpse.", completion = "<Walden flips through the battle plan.>\n\nIt looks like the reinforcements from the ships in Gilneas are marching soon. Crowley and Bloodfang have set up an encampment to the southeast for the Gilneas Liberation front.", sourceObjectiveStatus = "unverified-source-field" }
quests[27578] = { id = 27578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan's Fruition", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", sourceObjective = "Kill Emperor Dagran Thaurissan.", completion = "You've done it! You've actually done it! Morgan's years of planning and waiting have finally come to fruition.\n\nShe may have lost her land and family when Ragnaros tore this land asunder, but with the Dark Iron crippled we'll be able to safely build a new kingdom of our own in the Burning Steppes. Not even the Firelord himself will be able to breech the capital's walls!\n\nMake sure you come back someday when we've finished, you'll be our guest of the highest honor. I thank you with all my heart, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27579] = { id = 27579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "Da Twilight's Hammer be here for some reason. We don't know why, but Thal'trak be lettin' you in on a lil' secret of ours - da rogue Lexlort waits outside da hall where High Interrogator Gerstahn be so he can kill her if he gets da chance.\n\nShe's too smart for dat, though, so you gonna go in an' do it, ya? Go talk to Lexlort and let him know. I'm sure he be ok with it.", sourceObjective = "Find Lexlort.", completion = "Get over here. If you blow my cover, I swear to the Warchief I'll kill you where you stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27580] = { id = 27580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing Discord", description = "The Alliance reinforcements have established a foothold in the southwest region of Silverpine called 7th Legion Base Camp. Our primary goal at the base camp is to sow discord amongst the troops. This is a lightning fast assassination mission to kill their field commander, General Marstone. His death won't stop the Alliance advance, but it will certainly soften their ranks.", sourceObjective = "Assassinate General Marstone.", progress = "Marstone is a decorated field general. He will not go down easy.", completion = "The rest of the Alliance fleet will arrive shortly, only to find their base camp decimated. Now for the second and most important part of our battle plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27581] = { id = 27581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "Gerstahn is too heavily guarded and too smart to leave her post, so I'm not going to kill her.\n\nYou are.\n\nI'll throw in a little something I picked up off of a guard to make it worth your while.", sourceObjective = "Kill High Interrogator Gerstahn.", progress = "Does it look like I want to be waiting her any longer than is necessary?", completion = "The Twilight's Hammer's presence only complicates our mission here further, but you've done your part for now.  You've earned a reward for your efforts...and some rest. Let's get out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27582] = { id = 27582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "We're fighting a losing battle right now, I'm afraid. The Dark Irons would be difficult to defeat on their own, but their elemental allies have given them new bleeding edge warriors that we simply can't compete with.\n\nI need you to help us infiltrate their domain and kill as many of their vital leaders as possible. Hopefully that will shock their forces and turn the tide in our favor. Report to Razal'blade for further instruction. He's stationed beyond this gate and to the right.", sourceObjective = "Speak to Razal'blade.", completion = "Beyond this door lies the commander of the Dark Iron Army, surrounded by trained soldiers. Are you up for a little killing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27583] = { id = 27583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Flank", description = "I have ordered a defensive perimeter set up on our northern coast, at the Slithering Cove. Our scouts reported that the naga were trying to make landfall there.\n\nGralok is in charge of the operation - report to him and secure that beach!", sourceObjective = "Report to Gralok at the Slithering Cove in Twilight Highlands.", completion = "Warlord Zaela sent you? Good.\n\nIf you Horde are as strong as your Warchief promised, I expect to see some bloodshed on these shores.", sourceObjectiveStatus = "unverified-source-field" }
quests[27584] = { id = 27584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Surf", description = "These naga scum think to move upriver to reinforce the Bastion of Twilight. We will RIP off their fish heads and PULL OUT their SPINES.\n\n<Gralok drives his broadsword into the dirt.>\n\nDestroy the Blackscale!", sourceObjective = "Slay any combination of 15 Blackscale Raiders or Blackscale Mistresses.", completion = "<Gralok sizes you up.>\n\nYou're a true fighter, {name}. I liked watching you work. Perhaps the Dragonmaw really DO belong in your Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27585] = { id = 27585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The 109th Division", description = "General Angerforge and Golem Lord Argelmach are directly responsible for the horrific slaughter of the 109th Division of the Kargath Expeditionary Force. There were a lot of good trolls and orcs in that division, many of them my close friends.\n\nWell, young {race}, it's time for our fallen brothers to at last have their revenge.\n\nUnlock The Shadowforge Lock, go up the stairs and bear left until you reach the West Garrison. Kill Angerforge and Argelmach, and don't you dare show them any mercy.", sourceObjective = "Kill General Angerforge and Golem Lord Argelmach.", completion = "Up ahead is the Grim Guzzler. A disgusting bar full of all our enemies, intoxicated and therefore unfit for proper battle.\n\n<Hierophant Theodora Mulvadania grins.>\n\nRipe for the slaughter.", sourceObjectiveStatus = "unverified-source-field" }
quests[27586] = { id = 27586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shells on the Sea Shore", description = "I salvaged these mortars from the wreck of our airship when she detonated above Dragonmaw Port. But ammunition is in short supply!\n\nWhile you're running along the beach, do me a favor and pick up any unexploded mortar shells you find.\n\nUnexploded shells are the best kind - you never know WHEN they're going to go off. Perfect for surprising an enemy!", sourceObjective = "Gather 8 Unexploded Mortar Shells along the beach at Slithering Cove.", progress = "Do you have the shells? Hand them here!\n\n...Gently!", completion = "Oh yeah. YEAH! These are DEFINITELY going to kill somebody.\n\nProbably naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[27587] = { id = 27587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maliciously Delicious", description = "You know, I've got a problem you might be able to help me out with, here.\n\nSee, in addition to the fine pursuit of arms dealing, I'm trying to liven up the entertainment here in Bogpaddle. Apparently there's a bunch of these makrura things in the north waters that don't take kindly to the wild beach parties we've been throwing.\n\nJoke's on them. I'm not gonna be pushed around by giant lobsters; they're my next source of revenue! You bring me some of their tails and we'll turn a problem into profit.", sourceObjective = "Collect 6 Intact Swampshore Tails from Swampshore Makrura.", progress = "You got those tails? Don't be tryin' to push no hacked-up ones on me!", completion = "I can see it now: our own famous Bogpaddle Lobster-Poppers! Made fresh from the sea! Oh, it's like this stuff writes itself...\n\nYour help is very much appreciated, my friend. I'll start seeing if I can't cut your people a favorable arrangement, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27588] = { id = 27588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27589] = { id = 27589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Everyone inside the Grim Guzzler is absolutely hammered and, therefore, easily angered. I think we can seriously hinder the Dark Irons by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Thunderheart when you're done.", sourceObjective = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "I hear quite the commotion coming from the Grim Guzzler. I see you've been hard at work.\n\nIf you'll direct your attention opposite me, you'll notice that we have bigger issues to worry about than toying with drunkards.", sourceObjectiveStatus = "unverified-source-field" }
quests[27590] = { id = 27590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27591] = { id = 27591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Inside this chamber lies Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them all, and may this unholy union cease.", sourceObjective = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27592] = { id = 27592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drinks on the Rocks", description = "What's up, \"bro\"! We were just in the middle of our completely spontaneous beach party when something terrible happened, \"dude\"!\n\nI had a whole case of Silversnap Ice, the Baron's own drink of choice, until the silt crawlers stole them! I've never seen crawlers drink, but they took them right into the water and down the beach! We need some sort of awesome hero who can help retrieve our specifically-branded favorite beverage!\n\n<Brono stares at you a moment.>\n\nThat means you, \"brah\"!", sourceObjective = "Collect 10 bottles of Stolen Silversnap Ice from Silt Crawlers.", progress = "You got the goods, \"bro\"?", completion = "Our ice-cold, refreshing Silversnap Ice! I can't thank you enough, \"dawg\", for this entirely spontaneous act of heroism!\n\nHere, have your very own bottle as a totally sincere gesture of thanks! Be sure to tell ALL YOUR FRIENDS how good it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[27593] = { id = 27593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebirth of the K.E.F.", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", sourceObjective = "Kill Emperor Dagran Thaurissan.", completion = "A true {class} if I've ever seen one! You've done the impossible! I knew we could count on you.\n\n\n\nAnd with that, I'd like for you to be the first to know that the Kargath Expeditionary Force is now officially back in business!\n\nI extend to you my personal gratitude for your efforts here. Remember always our motto: \"First in, last out, always victorious. Remember always Kargath.\"\n\nYou are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27594] = { id = 27594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Her Majesty's Secret Service", description = "Lorna Crowley, daughter of Lord Darius Crowley, is currently at the Gilneas Liberation Front camp, located near the Greymane Wall, to the southeast.\n\nOur primary mission is to infiltrate the camp and capture her alive. The Dark Lady believes that she will be able to use Lorna as a bargaining chip against Crowley. I say we just kill her and bring her back as Forsaken, but we must do as the Dark Lady commands.\n\nWe must hurry before the rest of the Alliance forces arrive.", sourceObjective = "Capture Commander Lorna Crowley and return her to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", completion = "You have done it! Finally, everything is in place. Should Crowley not accept our terms, his daughter will be turned.", sourceObjectiveStatus = "unverified-source-field" }
quests[27595] = { id = 27595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet Hadassi", description = "Prophet Hadassi is the wisest and eldest member of the Orsis tribe.\n\nHe has not been accounted for and his well-being is of vital importance.\n\nGo into Orsis and find him.  A great day of reckoning will come to the Al'Akir's lackeys if he's been hurt.", sourceObjective = "Find the Prophet Hadassi in Orsis.", completion = "Who... who are you?  Sent here... to rescue my people and fight our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[27596] = { id = 27596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to The Black Vault near the Hall of Crafting, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", sourceObjective = "Obtain the Heart of the Mountain.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, {name}, take this as payment!", sourceObjectiveStatus = "unverified-source-field" }
quests[27597] = { id = 27597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crazy Larry", description = "You're gettin' it, {name}. You scratch my back, I scratch yours. Well, more like I scratch the back of your whole army, and just a little harder than the backs of the other side! Was that too complicated?\n\nWhat I'm sayin' is, that's a lot of backs. So I'm gonna have to ask you to scratch mine a few more times. Whoever stole those landmines may have just hit our boys on the eastern shore.\n\nHead to our camp to the southeast and check on Crazy Larry; he'll fill you in when you get there.", sourceObjective = "Find Crazy Larry to the southeast of Bogpaddle.", completion = "Silversnap sent you?! I'm DOOMED!\n\nOh, he sent you to help me! That's different, haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27598] = { id = 27598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Gil", description = "Gilblins!\n\n<Larry stares at you silently for a while.>\n\nYou never seen a gilblin before? They're crazy! Crazier than me! I just blow stuff up for a living, these guys are WHACKED!\n\nDunno where they came from, but they're like awful fish goblins! Gills and everything! They wiped out all my men down at the beach, and they took our shipping freighter!\n\nYou gotta help! They're just down to the east, go on and get rid of those gilblins!", sourceObjective = "Slay 7 Gilblin Stalkers.", completion = "That'll show those fish-faced freaks! Good work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27599] = { id = 27599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Take It With Them", description = "Any shipping crew I had that you don't see hanging around this camp are DEAD! Those were some fine goblins, but what's worse is they're all still out there! It's a TRAGEDY!\n\nI mean, it's a tragedy they still have all their stuff! It's horrifying to think of all the perfectly good materials and coins sitting out there in the water.\n\nHey! You can do me a favor! If you're killing gilblins out there, go get the ditty bags off my old crewmen!\n\nC'mon, they're not gonna need it anymore! Be real!", sourceObjective = "Collect 6 Ditty Bags from Deceased Bogpaddle Privateers.", progress = "You get those ditty bags? I hope you left the goblins there!", completion = "WOW!\n\nI don't know why I said that. I'm excitable! But man, there was a lot of stuff on these guys, check it out!\n\nHere, you want this?", sourceObjectiveStatus = "unverified-source-field" }
quests[27600] = { id = 27600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In With a Bang", description = "Our trade frigate's still all the way out there on the water, swarming with Gilblins! AHH!\n\nSorry about that. But really! We need a way to get you out there and get back our stuff. There's quality goods left on that ship! QUALITY! LIKE MY MIDDLE NAME!\n\nLucky for you, I have an idea! Head right outside the camp and check along the north wall... my son Jerry'll get you over there with our cannon! If he's been practicing, that is!", sourceObjective = "Speak with Lil' Crazy Jerry to board the ship, then retrieve all three of Crazy Larry's important goods.", progress = "You got it? Did you get it? Did you try the cannon? You didn't explode!", completion = "My high-grade fuse! My imported blasting powder!\n\nAnd my--hello there! I'll just be taking that!\n\nThose are all worth more gold than what you're wearing, you know! Thanks for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[27601] = { id = 27601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cities in Dust", description = "Our armies clash across the battlefield. Crowley and his forces are losing ground and they do not yet know the fate of Lorna Crowley. We will meet with Crowley and his compatriots at mid field and I will present them with terms of their surrender. They will either accept or we will kill them all and leave their cities in dust.\n\nAs my most trusted soldier, you are to stand by my side during the exchange. Tell me when you are prepared to leave.", sourceObjective = "Accompany Lady Sylvanas Windrunner to the Battlefield and defeat the Alliance!", completion = "<Lady Sylvanas Windrunner grimaces in pain.>\n\nThis... is not over. Godfrey and his traitorous allies will pay for what they have done as will the remaining Alliance forces occupying Lordaeron.\n\nOur work has only just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27602] = { id = 27602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet's Dying Words", description = "We... are... bound by oath... to protect the scepter of Orsis.\n\nListen, {class}, I don't have much time... left.\n\nFind the sacred receptacle... in the southern end of the city.\n\nDo not... let it... fall into their... hands...", sourceObjective = "Find the Sacred Receptacle.", completion = "Though the chest is locked, there is a plaque bearing interesting hieroglyphs above it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27603] = { id = 27603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sealed Gate", description = "At one end of the Dark Iron Highway stands a massive gate much like the one that protects Shadowforge City on the opposite side. However, we have no idea what's behind it!\n\nAll we know is that it's heavily guarded by Anvilrage patrols and the molten giant Bael'gar. You simply must dispose of them and see if you can pry that gate open!\n\nJust imagine what could lie behind it...there could be an entire other half of the city we never knew about! Or nothing! Who knows!\n\nThough, it's probably something...", sourceObjective = "Kill Bael'gar.", progress = "Were you able to get past the gate? Or scale it? What's behind it???", completion = "Darn it! I simply HAVE to know what's behind that gate! This could be the discovery that makes my career, you know!\n\nHmm....maybe a couple good explosions would do the trick...", sourceObjectiveStatus = "unverified-source-field" }
quests[27604] = { id = 27604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an the Prophet", description = "Jammal'an the Prophet, leader of the Atal'ai and Hakkari trolls, has obtained a small amount of Hakkar the Soulflayer's blood. They are injecting it into the green dragons to use their bodies to produce the massive quantities of blood necessary to summon Hakkar into our world.\n\nWe cannot allow this to come to pass. Slaughter Jammal'an and his priests before they get any further in their efforts!", sourceObjective = "Obtain Jammal'an the Prophet's Head.", progress = "Were you able to kill Jammal'an? I'll need proof that the deed is done.", completion = "Excellent! I suspect that without Jammal'an's leadership, the trolls will fall to infighting and Hakkar will never set his eyes upon our world.", sourceObjectiveStatus = "unverified-source-field" }
quests[27605] = { id = 27605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus", description = "The Hakkar blood the Atal'ai have been injecting into the green dragons has had devastating effects on the dragons themselves. It appears that these dragons, former jailors of the Atal'ai, have been corrupted by its presence in their bodies and have become creatures of Nightmare.\n\nEranikus, Ysera's primary consort and lead watcher over the temple, was infused with the largest quantities of blood and has become twisted beyond imagination. After Jammal'an is dead, find Eranikus and end him.", sourceObjective = "Kill Eranikus.", completion = "You only defeated Eranikus' Shade? This is most troubling...\n\nLet us hope that his full form does not still exist outside the Temple. Only Ysera herself is stronger than him in our flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[27606] = { id = 27606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast Him!", description = "Let's go fishing, {name}! Now that the mortars are ready, we can take out the leader of this invasion.\n\nFathom-Lord Heth'Jatar rules over the Blackscale warrior caste. Go to the Heth'Jatari Banners just northeast of here and honk this conch shell. It's like a dog-whistle. For fish.\n\nWhen Heth'Jartar shows up, I'll order the mortars to concentrate fire. You'll see the targets of the incoming shells.\n\nLure Heth'Jatar into our mortar fire and pummel him into submission!", sourceObjective = "Blow the Heth'Jatari Conch next to a Heth'Jatari Banner. Kill Fathom-Lord Heth'Jatar. Luring him into incoming mortar fire will help.", completion = "Boom baby, boom!\n\nWhat? You killed the Fathom-Lord already?\n\nI suppose we should stop shelling his corpse, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[27607] = { id = 27607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Flank", description = "Our new arrangement with the Horde will put my people in direct conflict with the Alliance.\n\nBring. Them. On.\n\nAs we speak, the Alliance moves up the peninsula to threaten Dragonmaw Port.\n\nFind Rok'tar to the south - I believe he has set up a command post on one of the shipwrecks - and ensure that the Twilight Shores remain in our control.", sourceObjective = "Speak with Rok'tar at the Twilight Shores in Twilight Highlands.", completion = "Good timing, {class}. We were just about to unleash a counter-attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[27608] = { id = 27608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "We're about to launch the attack upon the Twilight Gate, but there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nWould you go back in there and kill them?You will be able to choose one of these rewards:", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27609] = { id = 27609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now, while we're about to launch the attack upon the Twilight Gate, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nPlease head back in and kill them.You will be able to choose one of these rewards:", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27610] = { id = 27610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "If the Alliance gains control of this peninsula, they will threaten Dragonmaw Port. Not going to happen.\n\nSouth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand all along the shore!\n\nRush over there and scout the beach head control point. It's marked by that enormous flag. Then return to me.\n\nYou don't have to capture it, unless you're spoiling for a fight with the Alliance.", sourceObjective = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", progress = "What's the state of the beach head, {name}?", completion = "Good work, {class}. Now you know the lay of the land.\n\nIf you're ever having difficulty fighting here on the Twilight Shores, remember that capturing and holding the Beach Head will give all Horde forces here a combat advantage!", sourceObjectiveStatus = "unverified-source-field" }
quests[27611] = { id = 27611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Sand", description = "Our objective in the Twilight Highlands is to storm the Bastion of Twilight, but the Alliance have decided to make war.\n\nSo we will give them war!\n\nSlay their marines until the lesson is learned.", sourceObjective = "Slay 12 Highbank Marines on the Twilight Shores in Twilight Highlands.", completion = "Good, good. Let them reap what they sow!", sourceObjectiveStatus = "unverified-source-field" }
quests[27612] = { id = 27612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory From Within", description = "A few of our men didn't make it through portals which were supposed to open inside this very abbey.  You've already proven your elusiveness and battlehardiness... now I need you to do so again.\n\nThe abbey has two wings: a library, and a hall of arms.  In each wing, you should find a portal.\n\nUse this keystone on these portals.  Doing so should force them open, allowing our remaining shock troopers to take this abbey.", sourceObjective = "Open the Argent Portals in the Library Wing and the Hall of Arms within the abbey in Tyr's Hand.", completion = "The abbey will fall shortly.  We can soon move on, deeper into Tyr's Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27613] = { id = 27613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassin", description = "The fate of the Scarlet Crusade is tragic, if somewhat ironic.  At one point, they led the charge of humanity against the undead.  Now, they resemble those corpses that they once hunted.  What caused their descent into undeath isn't certain, but it doesn't make them any less dangerous.\n\nOne of their deadliest was an assassin who went by the name of Rohan.  We have intel that places him atop the bell tower in this very abbey.  Find him and kill him, {name}.  And try not to die on the way.", sourceObjective = "Kill Rohan the Assassin within the abbey bell tower in Tyr's Hand.", progress = "Fight well, {name}.", completion = "The death of Rohan eases my spirits a bit.\n\nI once fought beside him, you know.  He was an emissary of the Scarlet Crusade; one of the few that deigned to join us in our battle against Kel'thuzad, so many years ago.  How quickly things change.", sourceObjectiveStatus = "unverified-source-field" }
quests[27614] = { id = 27614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Salvage", description = "This battle was won before it started.  Right now, we're just shooting for style points.\n\nWithin these barracks, the sniveling Scarlet Crusaders cling to their priceless artifacts, even though some of the objects are too holy for their now-undead hand to touch.  So they keep them in chests, hidden from the world.\n\nYou will find these artifacts, and bring them back to me.  They belong to be among the Argent Crusade.  They belong in the hands of the righteous.", sourceObjective = "Obtain the Crimson Boar, Lihanna's Strand, the Shroud of Uther, and Gavinrad's Sigil.", progress = "I hope you gave them a fight.", completion = "Well done, {name}.  I will deliver these to Tyrosus when we return.", sourceObjectiveStatus = "unverified-source-field" }
quests[27615] = { id = 27615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrathcaster", description = "One of the more vile members of the Scarlet Crusade, Mataus the Wrathcaster, lurks within the barracks' dungeon.  Undeath suits his dark manner.\n\nWere I younger and on the front lines, I'd run him through myself.  As things are, I'm left behind to lead our forces from the rear.  So I leave the pleasure to you.", sourceObjective = "Slay Mataus the Wrathcaster.", completion = "You are well on your way to becoming a true champion of the Light, {name}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27616] = { id = 27616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Huntsman", description = "We've already lost half a dozen men to a hail of bullets and arrows coming from atop this fortress.  I haven't seen the face of the enemy that's firing, but I don't need to.  I know the name of the man up there.\n\nLeopold.\n\nThat's right, there's only one man up there, picking off my men one-by-one.  And from what I can see, there's only one of you.\n\nSounds like a fair fight to me.", sourceObjective = "Slay Huntsman Leopold.", completion = "One less thing to worry about.  Nice work up there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27617] = { id = 27617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befouled No More", description = "Can you sense it?  The taint is already lifting from this building.\n\nA holy building wants to be holy, and villains like Rohan and the rest of his Scarlet scum only hold it back.\n\nWith the abbey secure, we are a step closer to taking Tyr's Hand.  Report the results of our strike to Angela.  She should be leading the charge on the cathedral from somewhere in the center of town.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "Good, the abbey is ours.  I never doubted Eligor's ability for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27618] = { id = 27618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Upheaval", description = "I'll say we've done enough damage to these barracks to call this a win.  A commander, a huntsman, and a warlock, all slain... not to mention the relics that we've liberated.  Or shall I say... YOU liberated.\n\nThe cathedral still remains, but not for long.  Talk with Archmage Angela Dosantos, in the central courtyard.  The fate of Tyr's Hand's cathedral falls in her able hands.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "It sounds like Korfax really cleaned house over at the barracks.  It's very much like him to show off like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27619] = { id = 27619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Commander", description = "Scarlet Commander Marjhan is cunning, shrewd, and willing to do anything to win a battle.  Before all these things, however, she is loyal.\n\nI have no doubt you'll find her in the barracks' central chamber, fighting under a crimson banner, until she either wins or dies.\n\nMake sure it's the latter.", sourceObjective = "Slay Scarlet Commander Marjhan.", completion = "Good, good.  These barracks are as good as fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27620] = { id = 27620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Rats", description = "Well, I'm glad that Eligor and Korfax left some fun for me.  It was a battle unto itself to keep them from rushing headlong into the middle of this cathedral.\n\nThat's YOUR job, after all.\n\nThe cathedral lies ahead of us, the last real bastion of Scarlet power remaining.  Within it, Crusader Lord Valdelmar sits atop Tyr's Hand's crumbling pulpit of lies.\n\nThere will be no escape; there will be no mercy.  The last simpering vestiges of the Scarlet Crusade end here.  Slay him.", sourceObjective = "Slay Crusader Lord Valdelmar.", completion = "While I can't agree with their methods, I can't argue with their results.  In many ways, the Scarlet Crusade were well-intentioned, but their zeal grew too strong, and their hate blinded them to reason.\n\nI only hope that the same doesn't happen to our Brotherhood of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[27621] = { id = 27621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard's Patrol", description = "I was on my way to join Firebeard's Patrol when my bird was shot down.\n\nTwilight's Hammer launched surprise attacks all over the Highlands. Sometimes their buildings crawled right out of the earth in the middle of our villages. It was a nightmare!\n\nIn the chaos, Firebeard is one of the few who's kept his head on straight. He's trying to piece together a full gryphon wing from the survivors.\n\nIf you want to bring the Wildhammer into the Alliance, start by helping out Firebeard, to the west.", sourceObjective = "Seek out Keegan Firebeard at Firebeard's Patrol in Twilight Highlands.", completion = "Come to join the patrol, lad? Glad to have ya.\n\nI need some bodies helpin' to get our defenses under control here. Help me out and I'll see if I can't find some more prestigious work for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[27622] = { id = 27622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo' Better Shredder", description = "{name}, I've got plans for a better shredder. But my engineers can't wade into a combat zone alone.\n\nGo locate a salvageable shredder in the Twilight Shores, and use it to signal one of my salvage experts to join you. Defend the shredder while we make some \"upgrades.\"\n\nThe Alliance won't know what hit them! At least, not until my marketing campaign kicks in!", sourceObjective = "Locate a Salvageable Shredder on the Twilight Shores, and use it to summon a Bilgewater Salvage Expert. Defend the shredder until it is operational again.", completion = "That's right baby! That's right! Cold steel and hot death!\n\nWhat should we name our new creation? The Gnugatron? No - better - the {name}-o-matic. That's got a ring to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27623] = { id = 27623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Guardians", description = "The chest containing the scepter appears to be magically sealed and will not budge.\n\nThe plaque above it depicts two giant statues holding star and moon-shaped stones sockets at their center.\n\nThe two statues are pictured guarding pyramids that look like the ones outside.\n\nPerhaps it's worth your while to investigate these.", sourceObjective = "Obtain the Stone of the Moon and the Stone of the Sun from the Colossal Guardians.", progress = "You wipe away the sand from the hieroglyphs only for them to become covered in a new layer.  You'd best hurry.", completion = "You place the two gems inside the sockets in the wall.", sourceObjectiveStatus = "unverified-source-field" }
quests[27624] = { id = 27624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Fall", description = "Aww, that was nothin', really.\n\nThose statues were teetering as it was - just needed a little push is all.\n\nHow about you go and sort through that rubble?\n\nI've got a feeling we're close to getting this all sorted out.", sourceObjective = "Collect the Orb of the Morning Star, the Orb of the Evening Star, Orb of the North Star and the Orb of the Shooting Star.", progress = "Find anything interesting, {name}?", completion = "Fine work, {name}.\n\n\n\nIt looks as though our work here is nearly complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[27625] = { id = 27625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Quel'Danil", description = "The undead are here! The Forsaken! They've been moving closer and closer, but to launch an all-out attack on us... those horrid abominations!\n\nThe young draenei I was charged with have trained with the Highvale elves in combat. They are not defenseless, but they need help!\n\nPlease, {name}, assist them! Drive back the Forsaken!", sourceObjective = "Slay 16 Deathstalker Invaders at Quel'Danil Lodge.", completion = "Such aberrations in the face of the light... You are brave to face them, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27626] = { id = 27626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highvale Documents", description = "The Highvale have kept detailed records here for years. Deaths, births, seasons... but also vital scouting information and methods of contact with the rest of the Alliance.\n\nThe documents will be scattered in the chaos. If they fall into the hands of the Forsaken, more lives could be at risk! Please, you must retrieve the documents before they are taken by the Horde...", sourceObjective = "Collect the Highvale Report, the Highvale Records, and the Highvale Notes.", progress = "Are they safe?", completion = "Thank the Light. We will not let the Forsaken have anything that can be turned against us, no matter how small.", sourceObjectiveStatus = "unverified-source-field" }
quests[27627] = { id = 27627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Fancy Cockroach", description = "Evidently, the ancient statues were home to various species of scarab.\n\nDetermined to leave this site in the best condition possible, you resolve to ridding the chamber of these pests.", sourceObjective = "Kill 5 Amethyst Scarabs, 5 Sapphire Scarabs, 5 Turquoise Scarabs, and 5 Emerald Scarabs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27628] = { id = 27628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Word to Phaoris", description = "Hurry, {name}.  We must speak to my brother, the king.\n\nHe is bent on averting war with Al'Akir and the Neferset.  He has foolish hopes that there is a diplomatic solution to this problem.\n\nMaybe once he hears what occurred here he will see reason.", sourceObjective = "Speak to King Phaoris at Ramkahen in Uldum.", completion = "This is just the beginning, {name}.  If Deathwing's minions can bury entire cities, we have little chance of defeating them through conventional means.", sourceObjectiveStatus = "unverified-source-field" }
quests[27629] = { id = 27629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vizier's Vote", description = "Getting Vizier Tanotep to go against my brother's wishes is going to be extremely difficult.  His very position is based on enforcing the will of Phaoris.\n\nI've had little luck making the case for open war against Neferset.\n\nNevertheless you must speak to him.  Perhaps he will listen to an outsider's perspective.\n\nYou will find the Vizier at the Akhenet Fields on official business.", sourceObjective = "Speak to Vizier Tanotep at the Akhenet Fields in Uldum.", completion = "What manner of creature are you?  You will leave the king's lands before...\n\nWait!  You are that {name} I've heard so much about.\n\nYou must pardon my lack of hospitality.  We have seen all manner of hostile intruders since the barrier around Uldum failed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27630] = { id = 27630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Priest's Vote", description = "High Priest Amet's vote is the only one that is completely outside of our control.\n\nHe will vote as his divinations tell him and nothing we do will dissuade him.\n\nI figure that gives us even odds either way.\n\nThe only problem we face is that his clairvoyance has failed him ever since the barriers around Uldum fell.\n\nHe will not cast a vote unless he regains power over his divinations.\n\nTake the stairs at either side of the Vir'naal Dam and Speak to him to see what you can do to help.", sourceObjective = "Speak to High Priest Amet inside the Vir'naal Dam in Uldum.", completion = "War, you say.\n\nDivinations for war are always difficult.  Some wars must never be fought, even if victory was assured.  Some wars have to be waged even if defeat is certain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27631] = { id = 27631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Commander's Vote", description = "If we're to pass a resolution for war, the high council's vote needs to be unanimous.\n\nI'm certain High Commander Kamses will give us his vote once he hears about what happened at Orsis.\n\nPlease speak to him in Ramkahen and make sure that's the case.  I must make preparations in case our plan fails.", sourceObjective = "Speak to High Commander Kamses at the Ramkahen Legion Outpost in Uldum.", completion = "No need to fill me in on the events in Orsis, {name}.\n\nI've heard about them already.  And about you.  Any enemy of Al'Akir is a friend of mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27632] = { id = 27632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanotep's Son", description = "I have devoted my life to serving the King.  That service is unrivaled in importance by anything... with one exception: my son.\n\nTahet was captured by Neferset sentries.\n\nThey claim my son was trespassing upon their territory.  Phaoris is attempting to negotiate his release... but I fear for the worst.\n\nIf you were to find Tahet, I would pledge my vote to you.\n\nI do not know where they take the prisoners, but I've seen the guards consult maps to guide them through the thick vegetation.", sourceObjective = "Obtain the Vir'Naal Delta Map from a Neferset Guard.", progress = "This might be the map you're after.", completion = "You've obtained a map of the Vir'Naal river delta.", sourceObjectiveStatus = "unverified-source-field" }
quests[27633] = { id = 27633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood God Hakkar", description = "Hakkar... The mere mention of The Soulflayer's name will send many running. In the Sanctum of the Fallen God the Atal'ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area.\n\nPlace this egg in that sanctum, and it will force his summoning prematurely. {name}, do not hesitate. Strike once his avatar appears!", sourceObjective = "Kill the Avatar of Hakkar.", completion = "You have successfully stopped Hakkar here, but I fear we are far from done. The Atal'ai transported most of the blood they produced to Zul'Gurub, where the Hakkari work to summon The Blood God there.\n\n{name}, I do not think that this was ever meant to be the place of Hakkar's arrival - it was merely a test to see if the blood was potent enough! Hakkar can only be summoned in Zul'Gurub...and I fear we may be too late to stop the Hakkari with the blood they now have in their possession.", sourceObjectiveStatus = "unverified-source-field" }
quests[27635] = { id = 27635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decontamination", description = "You've been down here in Gnomeregan for a long time, {name}, and it's amazing that you've survived and kept your wits so long! We need to get you out.\n\nBefore we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500. It will do the rest! It shouldn't even hurt... much.\n\nWhen you're all done, check in with Technician Braggle and he'll make sure you get some suitable gear.", sourceObjective = "Board the Sanitron 500 to begin the decontamination process.", progress = "I bet you're feeling better already.", completion = "There, now you're fit to head off to the surface and start your new life. The High Tinker will be delighted to hear of your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[27636] = { id = 27636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "The SI:7 are all dead. Time to find Master Mathias Shaw.\n\nGood thing the squad commander told you where he would be.", sourceObjective = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the rest of my people?", sourceObjectiveStatus = "unverified-source-field" }
quests[27637] = { id = 27637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "That's a blow to our efforts. Damn Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Master Shaw.", sourceObjective = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27638] = { id = 27638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "The Kor'kron are all dead. Time to find Garona Halforcen.\n\nGood thing the squad commander told you where she would be.", sourceObjective = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the Kor'kron?", sourceObjectiveStatus = "unverified-source-field" }
quests[27639] = { id = 27639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "That's a heavy blow to our efforts. Damn that Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Garona.", sourceObjective = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27640] = { id = 27640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunwalds Don't Die", description = "As I understand it, you're to be looking to bring the Wildhammer clans together with the Alliance for war. Not sure you know what you're gettin' into.\n\nAnyway, if it's battle you're preparin' for, there's definitely one family you want by your side. Head southwest, to the opposite side of the Crucible of Carnage, and there you'll find Clan Dunwald's ruins. They're rightly ravaged, but that's not likely to be stoppin' the Dunwalds. It's just a matter of findin' them.", sourceObjective = "Look for Dunwald family survivors in the Dunwald Ruins.", completion = "If it's Dunwalds you be lookin' for, it's Dunwalds you've found. A couple of'm anyway. I can't find me other brothers for the life of me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27641] = { id = 27641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While Meeting The Family", description = "Hey there, <lad/lass>. I'm sure Keely's got you worrying about our brothers, but they can take care of themselves. They'll find their way back here one way or another.\n\nMaybe you can do me a favor while you're out meeting the family... Dunwald territory is still infested with Twilight's Hammer and their servants. I'd appreciate it if you could remind them that they're not welcome.", sourceObjective = "Kill 20 Twilight's Hammer in Dunwald territory.", completion = "Now that's what I'm talkin' about lad. My kinda {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27642] = { id = 27642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through The Wreckage", description = "The Twilight's Hammer were damn thorough when they sacked our town.  Me and me brothers may well be the only ones that held'm back. I gotta be sure though.\n\nAs you're siftin' through the ruins, keep an eye out for the bodies of me kinsmen. I wanna know if dere were any survivors... or if it seems like some might have gotten away.", sourceObjective = "Search for the bodies of 12 Dunwald Victims.", completion = "That many dead, eh? Not seemin' likely that anyone outside of me brothers fought through it then. I guess I already expected as much.\n\nThanks for takin' the time to look for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27643] = { id = 27643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnelly Dunwald", description = "So you be lookin' to find us, and I be lookin' to find me brothers. It sounds to me like we got some common ground in there abouts.\n\nDonnelly's our eldest, and while his size shows it, his wits might not. He's usually up in the northern ruins - in the hovel. Do ya think you might go lookin' for him for me? It'd be a right comfort if I knew he were safe.", sourceObjective = "Find Donnelly Dunwald.", completion = "Hi friend! I don't think I know you... I'm Donnelly Dunwald.\n\nWhat's your name? I don't think I know you... Do I know you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27644] = { id = 27644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eoin Dunwald", description = "Eoin's one of the twins. He's got a penchant for the drink. You'll likely be findin' him over by the old well - the ale stores were in a building there.\n\nMind making him to pay his worrying sister a visit? Shouldn't take much convincin' if you can get to the ale first.", sourceObjective = "Find Eoin Dunwald.", completion = "Of all the buildings in all the towns to collapse, why'd it have to be this one?!", sourceObjectiveStatus = "unverified-source-field" }
quests[27645] = { id = 27645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cayden Dunwald", description = "Cayden's the other twin. He's got a thirst too, but not for ale. I'm sure he's been havin' a grand time of it since the Twilight came to our doorstep. Gettin' some of that aggression out of his system mayhaps.\n\nI'm thinkin' the best place to go lookin for him is at market row, by the old smithy. He used ta hang out there anyway, but since that place is swarmin' with the most Twilight, he's probably got all the more reason to be callin' it home now.\n\nBring'm back for me. In one piece would be nice.", sourceObjective = "Find Cayden Dunwald.", completion = "Well look at ya, all geared and fancy. Keely send you to keep an eye on old Cayden, eh? Won't be needin' it. I got these louts handled.\n\nHahah! They chose the wrong dwarf to be ambushin' today! Ahahahahah!", sourceObjectiveStatus = "unverified-source-field" }
quests[27646] = { id = 27646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Beak", description = "I lost me gryphon. Beak! Where are you Beak?!\n\nWanna help me find him? I know he's in da hovel. He hasta be.\n\nBeak?! Wheres are ya?\n\nI hope he's okay.", sourceObjective = "Help Donnelly find Beak in Dunwald Hovel.", progress = "Did you find'm?! Please?", completion = "You found'm! You found Beak! I like you, new friend!\n\nI'm gonna go show Keely. Keely like Beak too.", sourceObjectiveStatus = "unverified-source-field" }
quests[27647] = { id = 27647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything But Water", description = "Look, buddy. Either you're here to help me find some drink, or you're in the way.\n\nWhy don't ya go down to the old storehouse and look downstairs. I had a mighty suspicion that ol' bookkeeper up in there was sneaking sips between pages. I bet he has a keg in his basement!\n\nIf ya find anything, come straight back to me! No dallyin'... this is urgent!", sourceObjective = "Check the cellar Eoin Dunwald mentioned for a keg.", progress = "You stink of sober! Find me some drink!", completion = "Donnelly's belly! That's more like it. Good to not be dyin' of the thirst again.\n\nHere, have some. Good ol' Eoin's never so impolite as ta not share!", sourceObjectiveStatus = "unverified-source-field" }
quests[27648] = { id = 27648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into The Fire", description = "Fine, fine. You want a piece of the action? You can join in.\n\nLet me know when you're ready ta go.", sourceObjective = "Accompany Cayden Dunwald through the somewhat obvious ambush.", progress = "They keep comin an' I'll keep swinging!", completion = "A thing of beauty, isn't it? An' they keep comin' back for more. Love it!\n\nI'll go find Keely and settle her nerves in a bit. Just one more go through the row.", sourceObjectiveStatus = "unverified-source-field" }
quests[27649] = { id = 27649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Supply", description = "Hey bud. Seeing as how you're so friendly and great and all, think you might do a dwarf a favor?\n\nThese are Dunwald ruins... there's SURE to be more stock in some of these buildings. If you come upon more ale, bring it my way, will ya? A good dwarf can never have enough!\n\nI'm thinkin' I'll find my way back to Keely, so ya might have to hunt me down, but I'll try'n make it worth it to ya.", sourceObjective = "Collect 6 Barrels of Wildhammer Ale.", progress = "Where's me booze?", completion = "Woooooh! That's exactly what my belly needs!\n\nYou get me all the nice things.", sourceObjectiveStatus = "unverified-source-field" }
quests[27650] = { id = 27650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Again", description = "Ya should find Keely. She'll be eager for word.", sourceObjective = "Speak to Keely Dunwald at the Dunwald Holdout.", completion = "Thank you for bandin' my brothers back together. I know they're tough, but they're even tougher when they're side by side, and there's a lot of Twilight out there.\n\nYou're good to put a gal's heart at ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[27651] = { id = 27651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing It Like a Dunwald", description = "They already left to hunt down the ettin that lead the attack on Dunwald. I asked them to at least give ya a chance to catch up, but I'm not sure waitin's in their blood.\n\nThey made off towards the town square, in the center of the ruins. You should go join'm before ya miss out on all the fun.", sourceObjective = "Speak to Flynn Dunwald and aid the Dunwald brothers in killing Darunga.", completion = "Thanks for your help. You've got a warrior's spirit in ya - you coulda fooled me for a Wildhammer if it weren't for your... well.. you know.\n\nI know Firebeard sent you to unite us. My love for that dwarf runs shallow, but you know now we've got plenty of reasons to make enemies of Twilight. If you see him, tell him that when the battle starts, the Dunwald family will be there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27652] = { id = 27652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted. I suppose that's what I get for hiding amongst the sheep.\n\n<Mathias studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice bunch of guys. Dead now. They're made from the souls of the most skilled killers.\n\nWant to do me a favor? Hunt them down. Bring back their soul pendants.", sourceObjective = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "I'm not sure what I'm going to do with all of these. I'll probably fence them and donate the proceeds to the Stormwind orphanage.\n\nNow to find someone sick enough to buy such a thing. It'll probably be a goblin. Or, a gnome warlock.", sourceObjectiveStatus = "unverified-source-field" }
quests[27653] = { id = 27653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted, {class}. But that's part of the fun of hiding amongst the sheep.\n\n<Garona studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice for a group of dead guys. They're made from the souls of only the most skilled killers.\n\nDo me a favor? Hunt them down.\n\nThey wear their souls in pendants about their necks. Bring them back to me. Souls optional.", sourceObjective = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "What do you think I should do with all of these? Maybe I'll melt them down and have the metal imbued into a new dagger that I can thrust into Cho'gall's chest.\n\nThink there's time for that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27654] = { id = 27654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "No foray into the field would be complete without a good old-fashioned take-the-bad-guys-out kind of mission.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, I'm sure you'll have plenty of targets.\n\nHow you choose to kill them is up to you.", sourceObjective = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", progress = "Looks to me like you might need to take out a few more. I'm just saying.", completion = "None of us are too good to get our hands a little dirty. Or bloody, in this case.", sourceObjectiveStatus = "unverified-source-field" }
quests[27655] = { id = 27655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "There's nothing worse than a self-hating Twilight's Hammer cultist. Nothing! These idiots actually want to bring about the end of the world.\n\nThat marks them for extinction in my book.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, you should have no shortage of targets.\n\nI could care less how you choose to kill them.", sourceObjective = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", completion = "Feels good to get a little blood on your hands, doesn't it? Especially when that blood belongs to such self-deluded fools.", sourceObjectiveStatus = "unverified-source-field" }
quests[27656] = { id = 27656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Croc-Out", description = "The Stagalbog east of town is swarming with crocolisks. Swarming, you hear me? I've sold every bit of crocolisk you could imagine.\n\nCrocolisk hides, teeth, tails, tongues, eyes, you name it. My point is, they ain't sellin' anymore. There's too many crocs! We're over-supplied and under-demanded.\n\nSo since they're of no use to me, and they occasionally eat my guests, I need you to just kill the suckers. Do me the favor, eh? I'll be here negotiatin' things with your people.", sourceObjective = "Slay 8 Sawtooth Crocolisks.", completion = "All taken care of? Good to hear. Takes a load off my mind.\n\nNow I can focus on proper business for the fine folk of Marshtide and Stonard, weary from the war... and all that junk.", sourceObjectiveStatus = "unverified-source-field" }
quests[27657] = { id = 27657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Mathias spits.>\n\nWe need help. There's an Earthen Ring woman, Earthcaller Yevaa, southwest at the Elementium mine.\n\nShe and her goblin initiate need help with the shutting down the elemental portals hereabouts. I'm thinking that in exchange, she can help us with our problem.", sourceObjective = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than happy to lend you whatever assistance that I can.", sourceObjectiveStatus = "unverified-source-field" }
quests[27658] = { id = 27658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Garona spits.>\n\nI hate to say it, but we need help. There's an Earthen Ring woman, a draenei named Earthcaller Yevaa.  She and her pet goblin are southwest at the Elementium mine.\n\nThey need help with shutting down the elemental portals around here. In exchange, she can help us with our problem.", sourceObjective = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than willing to help you in any way that I can.", sourceObjectiveStatus = "unverified-source-field" }
quests[27659] = { id = 27659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Overload", description = "I used to be the caretaker of the Earthen Ring's portals here. But while we were away helping to save Deepholm, the Twilight's Hammer moved in and corrupted the area.\n\nThey're using powerful ascendants to guard our portals. That's where they've made a critical error.\n\nI want you to go to the portals and use the controllers to overload them. This will unleash all of the portal's energy, debilitating the ascendant. Slay it.", sourceObjective = "Slay Debilitated Apexar, Debilitated Aetheron, and Debilitated Edemantus.", completion = "The last portal is deep within the mine here, but we'll deal with that in a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27660] = { id = 27660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Loch", description = "I have no knowledge of any artifact that Cho'gall is crafting, but I think I know one that can help.\n\nCountess Verrall is the ancient spirit of Loch Verrall to the north. She has no love for the Twilight's Hammer, who have polluted her waters.\n\nSeek her for the wisdom that you seek.", sourceObjective = "Speak with Countess Verrall at Loch Verrall in the Twilight Highlands.", completion = "I know why you are here, {name}. Your reasons sing within your fluids.\n\nI know about the dead dwarf forgesmith polluting my lake. If you want to find out what his corpse remembers, you must earn it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27661] = { id = 27661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire the Cannon", description = "My arch-nemesis, Lord Cannon, has foolishly decided to throw his allegiance to the Twilight's Hammer.\n\nIn the past, we've coexisted with a shaky truce, but his change of heart leaves me little choice but to put an end to him. Or, I should say, if you want the information that you seek from the dead dwarf, you're going to kill Lord Cannon for me.\n\nSeek him at Cannon's Inferno to the southeast.", sourceObjective = "Slay Lord Cannon.", completion = "I am pleased. Lord Cannon was always an unworthy adversary.\n\nVery well, {race}, I will help you gain the information which you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[27662] = { id = 27662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbinding", description = "Look, if there's one thing I know, it's elementals. I've been able to really gain an appreciation for how they feel. Let me tell you, they don't appreciate being enslaved one bit!\n\nSo, what I'm saying here is that if you were to free the enslaved elementals, I'm sure that not only would they show their gratitude, they'd also likely turn on their masters.\n\nSounds like a win-win to me, {name}.", sourceObjective = "Free 10 Enslaved elementals by slaying them at the Twilight Citadel.", completion = "What'd I tell you? Elementals aren't so bad after all, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27663] = { id = 27663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tastes Like Strider", description = "You there! Yes, you! You want a good word put in with the Trade Baron? Give me a hand!\n\nI heard you're the one that got all those makrura tails. They're wonderful, but not enough for proper swamp food. I need drumsticks for my gumbo!\n\nThere's plenty of swampstriders just outside town in the Sorrowmurk. I want the biggest drumsticks you can find!", sourceObjective = "Collect 9 Jumbo Swampstrider Drumsticks from Swampstriders.", progress = "Have you got those drumsticks?", completion = "Ah, good, good! Just what I needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27664] = { id = 27664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Volcanic Deck", description = "Now that you have gathered all of the Ember cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Volcanic Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Volcanic deck!   Congratulations!", completion = "So you have put together a deck of Embers.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27665] = { id = 27665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Hurricane Deck", description = "Now that you have gathered all of the Wind cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Hurricane Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Hurricane deck!   Congratulations!", completion = "So you have put together a deck of Hurricanes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27666] = { id = 27666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Tsunami Deck", description = "Now that you have gathered all of the Wave cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Tsunami Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Tsunami deck!   Congratulations!", completion = "So you have put together a Tsunami deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27667] = { id = 27667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Earthquake Deck", description = "Now that you have gathered all of the Stone cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Earthquake Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete an Earthquake deck!   Congratulations!", completion = "So you have put together a deck of Earthquakes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27668] = { id = 27668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay Attention!", description = "Listen, {race}. It's not that I don't appreciate the rescue and all, but this is a dire situation.\n\nYou have to pay better attention out there!\n\nI was watching, and you passed right over a busted alliance crate.\n\nThere's bound to be something in there that could help me and my boys.\n\nHow about you get out there and take a look-see, hrm?", sourceObjective = "Nazgrim wants you to see what lies in the broken Alliance crate north of The Immortal Coil.", completion = "Sure enough...\n\nThis looks to be something that Nazgrim will take quite an interest in.", sourceObjectiveStatus = "unverified-source-field" }
quests[27669] = { id = 27669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Honors", description = "It looks like all that's left to do is to place the orbs on the pedestals at each corner of this mechanism.\n\nWe appear to have stumbled upon what may be the most important find in modern history.\n\n<Harrison looks at you for a moment, then hands you the orbs.>\n\nWell, go ahead, {name}.\n\nWe'd have never made this discovery without you.", sourceObjective = "Use the Orbs of the Stars near the mechanism in the Chamber of the Stars.", completion = "Well, now. Would ya look at that!\n\nAs amazing as this is, I am confident that there's more to our discovery than meets the eye...\n\nMuch more.", sourceObjectiveStatus = "unverified-source-field" }
quests[27670] = { id = 27670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinned Down", description = "My name is Nevin Twistwrench and I'm the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E.\n\nI don't know how you managed to survive the radiation down here, {name}, but most of the others haven't fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They've lost their minds!\n\nIf you're still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?", sourceObjective = "Kill 6 Crazed Leper Gnomes.", progress = "Help my men get the way cleared out so we can help the other survivors get out of here!", completion = "Well done, {name}. My men can take it from here. Let's focus on getting the other survivors out now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27671] = { id = 27671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See to the Survivors", description = "If we don't do something quick, neither Nevin nor the survivors will make it out of here alive. I'm going to give you my squad's emergency teleport beacon. We still have enough strength and ammunition to fight our way out of here, but those survivors are in no condition to make a run for it.\n\nUse the beacon on survivors to arrange for them to be teleported out of here to the safe area my men have set up. Once you've done that, report back to me and we'll make arrangements to get you out of here.", sourceObjective = "Use the Teleport Beacon to teleport 6 Survivors to safety.", progress = "Nevin's team found a lot of survivors this time, but he's cutting it awful close.", completion = "I know Nevin will be pleased with all the survivors you managed to help. I still can't believe you managed to stay so strong down here in the radiation. You've seen the shape the other survivors are in.\n\nLet's get you to the loading room for decontamination.", sourceObjectiveStatus = "unverified-source-field" }
quests[27672] = { id = 27672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a door which leads to the legendary Chamber of Khaz'mul. Who knows what secrets could be hidden inside!\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to unlock the secrets of Uldaman!", sourceObjective = "Defeat Ironaya.", completion = "Don't worry about the chamber, my boys will check it out! You have more important things to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27673] = { id = 27673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's What's Inside That Counts", description = "The Makers built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI fear that one of the Old Gods is responsible for this, and you're going to help me see if that's the case! Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", sourceObjective = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Where are the cores, lad? By Muradin's Beard, where are the bloody cores?\n\n<Kand takes a deep breath.>\n\nSorry about that. Have you been able to obtain the cores?", completion = "This is incredible, {name}. The power coursing through each core...the contrasting powers so close together!\n\nI'll take this to the proper dwarves right away. These cores are extremely important!", sourceObjectiveStatus = "unverified-source-field" }
quests[27674] = { id = 27674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Surface", description = "Nevin has just sent word that he and his men are making their way to the surface. He'll be waiting for you in the building that S.A.F.E. has established as its headquarters.\n\nSee Torben Zapblast over there? Talk to him when you're ready to head to the surface and he'll arrange to have you transported up there. It's been a pleasure meeting you, {name}, and I'm honored to have played a small role in helping you escape from Gnomeregan to start your life on the surface.", sourceObjective = "Speak to Torben Zapblast to get teleported to the surface and report to Nevin Twistwrench.", completion = "It's good to see you again, {name}. Without your help, we wouldn't have been able to get so many survivors out of Gnomeregan this time. Everyone is going to be thrilled to meet you and hear your story.", sourceObjectiveStatus = "unverified-source-field" }
quests[27675] = { id = 27675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Stormwind City to accept your forged documents.", sourceObjective = "Find a resident of Stormwind City to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27676] = { id = 27676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Explorers' League is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", sourceObjective = "Kill Galgann Firehammer.", completion = "Fantastic! Great work! We'll know all that Dig Three has to tell us in no time at all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27677] = { id = 27677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. The secrets on these discs could change everything about how we view our world. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe problem is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for the Explorers' League!", sourceObjective = "Defeat Archaedas.", completion = "Well done, lad! Now go to the discs and learn all you can!", sourceObjectiveStatus = "unverified-source-field" }
quests[27679] = { id = 27679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a locked door which I believe leads to the legendary Chamber of Khaz'mul. We do not yet know what artifacts wait inside it.\n\n\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to progress any further into this place.", sourceObjective = "Defeat Ironaya.", completion = "Reliquary agents are en route to investigate the chamber. You have more important matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[27680] = { id = 27680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. These platinum discs could grant our order unbelievable power. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe only problem in obtaining them is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for The Reliquary.", sourceObjective = "Defeat Archaedas.", completion = "You are a most reliable agent, {name}. Proceed to the discs and learn all you can. Report back to me immediately after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27681] = { id = 27681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Reliquary is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", sourceObjective = "Kill Galgann Firehammer.", progress = "Was old Galgann too much for a lowly {class}?", completion = "Well done. Dig Three and any secrets beyond that door will soon be ours and ours alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[27682] = { id = 27682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Minerals", description = "The Titans built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI suspect that one of the Old Gods is responsible for this, and you're going to help me see if that is indeed true. Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", sourceObjective = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Do you have the cores with you, or are you just here to chat? Perhaps we should stop this whole charade and enjoy some snacks and fine wine instead?", completion = "Both of these cores are still far more potent than most of the cores we use  to power our own protectors, and these are ancient devices!\n\nThank you, these will prove extremely valuable to our society.", sourceObjectiveStatus = "unverified-source-field" }
quests[27683] = { id = 27683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Woods", description = "I saw the strangest commotion coming through town the other day.  A horse-drawn cart, loaded with crates and chests, a worgen woman at the reins, a blood elf by her side, and a dwarven paladin running behind, yelling some of the most creative obscenities I've heard in quite some time.\n\nThey looked like they were headed to Eastern Plaguelands, though I'd imagine they can't be far past the Thondroril River by now.  I wonder what they were up to?", sourceObjective = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[27684] = { id = 27684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visitors", description = "My sources at the Menders' Stead have informed me that we will be having some visitors soon.  A group of paladins - led by a worgen tradeswoman, of all things - will be arriving here shortly.  I look forward to meeting them.  Particularly one of them.\n\nWould you mind stopping in and checking in on them?  I can't say for sure, but by the time you get there, they should just be crossing the Thondroril River, far to the west.", sourceObjective = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[27685] = { id = 27685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Deed Left Undone", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nSo... in our rush ta git over here, we left a little unfinished business off to the east a ways.\n\nA little lady was near death herself. We had no choice but ta leave her by a little air vent when we came here to yer rescue.\n\nHow bout yeh git over and help her while there's still time?", sourceObjective = "Speak to Adarrah in the Kelp'thar Forest.", completion = "Oh, finally...\n\nI don't know how much longer I can last!", sourceObjectiveStatus = "unverified-source-field" }
quests[27686] = { id = 27686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Orgimmar to accept your forged documents.", sourceObjective = "Find a resident of Orgimmar to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27687] = { id = 27687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opened Can of Whoop Gnash", description = "What an accomplishment, felling a  mighty sea giant!\n\nThe new residents of Smuggler's Hole will feel considerably safer knowing this monster is no longer loitering outside their haven.", sourceObjective = "Bring Gnash's Head to Samir in Smuggler's Hole.", progress = "You took down that Sea Giant, {class}?", completion = "It's not much, but it's all I've got down here.\n\nYou're more than welcome to it, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27688] = { id = 27688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that we need to eliminate: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI'd like for you to serve as my distraction. When the time is right, I'll step in and finish them off from behind.\n\nWhatever you do, {name}, do not underestimate them. Each got to where they are by being ruthless and very good at what they do.", sourceObjective = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight.\n\nWe work well together, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27689] = { id = 27689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that need killing: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI want you to serve as a distraction. When the time is right, I'll step in to finish them off from behind.\n\nJust make sure that whatever you do, you don't underestimate them, {name}. Each of those lunatics got to where they are by being ruthless and very good at what they do.", sourceObjective = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight. Not bad work, {name}. Not bad at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27690] = { id = 27690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, the Drake-Tamer", description = "{name}, the stronghold at Bloodgulch is the heart of the Dragonmaw empire in the Highlands. It is just up the river. Narkrall Rakeclaw is using his considerable power to amass a wing of drake-riders there.\n\nFor the Dragonmaw to succeed, Bloodgulch must succeed. Go to Narkrall and make sure it is so.", sourceObjective = "Report to Narkrall Rakeclaw at Bloodgulch in the Twilight Highlands.", completion = "<Narkrall sizes you up.>\n\nAnother mewling Horde whelp? Zaela saps our strength by diluting our forces with the weak. Very well, {class}. Prove yourself to me, and show me what your Horde is made of.", sourceObjectiveStatus = "unverified-source-field" }
quests[27691] = { id = 27691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshfin Madness", description = "I'm afraid the rest of the Steamwheedle here are gone. All the young ones at the camp to the east were lost when the murlocs came.\n\nYes, there's always been murlocs on these shores... but not in these numbers. They came in droves from the sea at night, howling and frothing, swarming up onto the land to attack!\n\nWe can't have them still running around, now can we? Would you put an old goblin at ease and go beat some of them back into the water?", sourceObjective = "Slay 12 Marshfin Murlocs.", completion = "You have to wonder just what's out there. This is the coast of the Forbidding Sea, with nothing beyond its reaches... but all these fishy folk just stomped right out of it.\n\nWhat's more, I saw where they've been going...", sourceObjectiveStatus = "unverified-source-field" }
quests[27692] = { id = 27692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Princess Theradras", description = "Do not be alarmed, young {race}. I am Zaetar, son of Cenarius, and I come to you for your assistance.\n\nLong ago, I made the mistake of mating with Princess Theradras, a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras' taint runs deep and threatens far more than just Maraudon.\n\nCome slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.", sourceObjective = "Kill Princess Theradras  and return to Zaetar's Spirit.", completion = "Thank you, {name}. As you can see, my mere presence here has resulted in a bloom of glorious life despite my mate's presence. Names aside, perhaps one day you will again venture into Desolace and find it a verdant oasis free of any traces of the Old Gods.", sourceObjectiveStatus = "unverified-source-field" }
quests[27693] = { id = 27693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", sourceObjective = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", sourceObjectiveStatus = "unverified-source-field" }
quests[27694] = { id = 27694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Tears", description = "The trolls that lurk within this temple have done grievious harm to my kind, {name}. We were sent here to guard this place, and were instead used to unleash the terrible powers within.\n\nI must beg you for the help only a mortal can give. You can be my hand within the temple; should I enter by myself, I risk being turned against my brothers as well.\n\nWe shall make a pact. If you wish to help, first gather Atal'ai artifacts from the waters around the temple, and return them to me.", sourceObjective = "Collect 5 Atal'ai Artifacts from the Pool of Tears surrounding the Temple of Atal'Hakkar.", progress = "Your gathering of these artifacts will be a sign of faith. Once rendered, I will perform the ritual.", completion = "The essence of the green dragonflight wafts from these artifacts; the vestiges of my corrupted kin. In purifying them, I form a bond between us.\n\nStep forward, {name}, and receive the Oathstone of Ysera's Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[27695] = { id = 27695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed too many red dragons, but one yet lives. Do you remember Lirastrasza? She's shackled nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut through her chains.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", sourceObjective = "Obtain the Elementium Axe.", progress = "Do you have the axe? They're going to kill Lirastrasza soon.", completion = "That thing looks sharp. Sharp enough to do the deed, at least.\n\nBut if I'm a judge of weaponry, that's not what Cho'gall's after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27696] = { id = 27696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed many red dragons, but one's still breathing. Do you remember Lirastrasza? She's chained nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut her free.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", sourceObjective = "Obtain the Elementium Axe.", progress = "Do you have the axe?", completion = "That's a very sharp axe. It'll do the job, but if I'm any judge of weaponry, that's not what Cho'gall's after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27697] = { id = 27697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption in Maraudon", description = "{name}, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon.\n\nLord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!", sourceObjective = "Kill Lord Vyletongue and return to Zaetar's Spirit.", completion = "Excellent work, {name}! Eliminating Vyletongue's presence is a key step to freeing me and, ultimately, saving these lands from corruption. Take this as a token of my thanks and an incentive to continue your work here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27698] = { id = 27698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Theradras", description = "Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon. Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction.\n\n{name}, venture forth and kill Noxxion and Razorlash. They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.", sourceObjective = "Kill Noxxion and Razorlash and return to Zaetar's Spirit.", completion = "Without her powerful servants, Princess Theradras is significantly more vulnerable. Find her lair, {name}...it is time to strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[27699] = { id = 27699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Weak", description = "That's one tough shark!\n\nYou determine that it's in everyone's best interest to try and distract Budd and hope his attention never returns to Gnaws and this Skeletal Reef.\n\nPerhaps the teeth of the beast will prove captivating enough...", sourceObjective = "Collect 5 of Gnaws' teeth from the Skeletal Reef.", progress = "Whatcha got there, pal?", completion = "What?!\n\nGnaws ain't dead?!\n\nThis kinda takes the quick outta my get rich quick scheme...\n\nThem giant shark teeth are nice and all, but we can't stop 'til that shiney is ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[27700] = { id = 27700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her.\n\nI need you to take the Elementium Axe and free her from her bonds.", sourceObjective = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", completion = "Isn't she a beauty?\n\nLet's see what she does now that she's free.", sourceObjectiveStatus = "unverified-source-field" }
quests[27701] = { id = 27701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her, {class}.\n\nYou need to take the Elementium Axe and free her from her bonds before they do.", sourceObjective = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", progress = "All you have to do is use the axe to break Lirastrasza's chains.", completion = "Isn't she beautiful? So graceful.\n\nI hope she gets her fill of revenge and then some.", sourceObjectiveStatus = "unverified-source-field" }
quests[27702] = { id = 27702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are drakes that she's downing that need finishing off, {name}. Wouldn't want the Twilight's healers to get them back up into the air.\n\nTime for a little Coup de Grace.", sourceObjective = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", progress = "Finish off more Twilight Skyterrors.", completion = "Our efforts to improve relations with the red dragons has really paid off, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27703] = { id = 27703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are still drakes that she's downing that need finishing off, {name}. We don't want the stinking Twilight healers to get them back up into the air.\n\nTime for a little Coup de Grace.", sourceObjective = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", progress = "That's all? I think that you can finish off a few more.", completion = "Good thing that you and Warlord Krogg made friends with the red dragons.", sourceObjectiveStatus = "unverified-source-field" }
quests[27704] = { id = 27704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of the Sunken Temple", description = "I will need you to enter the temple first, {name}. I can join you once a path is secure, but I dare not enter blindly. Turned against my kind, I would be a vicious enemy.\n\nYou can start by descending the stairs behind me. Then, swim through the flooded depths of the Broken Hall. Once there, follow the passageway to the right to find the Hall of Masks.\n\nBeware of any temple guards. Once you have found the Hall of Masks, I will contact you through the Oathstone.", sourceObjective = "Journey through the antechambers of the temple to the Hall of Masks.", completion = "This is it!\n\nThese are the bones of my kin...", sourceObjectiveStatus = "unverified-source-field" }
quests[27705] = { id = 27705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step One: The Priestess", description = "My bretheren are being butchered here. It's as I thought.\n\nI must ask your help further before I enter, {name}. In the passageway outside this room, the hallway proceeds left and right. To the right, it goes down to the Chamber of Blood. Here the Atal'ai perform their dark rituals.\n\nThey have expected and prepared for my kind for years, but not for you. Enter the Chamber of Blood and slay the Priestess Udum'bra. She is one of three foul presences here that must be vanquished before I may enter.", sourceObjective = "Slay Priestess Udum'bra in the Chamber of Blood.", completion = "Good riddance. Another source of corruption in this world put to rest.\n\nI thank you for your bravery, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27706] = { id = 27706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scepter of Orsis", description = "The chest below unlocks with a loud click as you insert the two stones into the plaque.\n\nObtain the scepter and bring it back to General Ammantep.", sourceObjective = "Obtain the Scepter of Orsis from the Sacred Receptacle.", progress = "You're back, {name}!", completion = "So... this is what Al'Akir wanted all along.", sourceObjectiveStatus = "unverified-source-field" }
quests[27707] = { id = 27707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neferset Prison", description = "Hieroglyphs depicting a chained Tol'vir mark the southeastern corner of the map.\n\nPerhaps Tahet was brought there when he was imprisoned.", sourceObjective = "Go to the Neferset Prison Camp and find the whereabouts of Tahet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27708] = { id = 27708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Time", description = "<Erunak's image penetrates your mind.>\n\nYou have done well, {name}, but more remains to be done.\n\nBefore moving on from this place, let us be sure that we leave it in disarray.\n\nFind the one who leads these naga and repay him for his misdeeds.", sourceObjective = "Erunak Stonespeaker wants you to slay Warden Azjakir at The Clutch.", progress = "Is it done, {name}?", completion = "It is good that this operation has been undone.\n\nSoon, I must move on...", sourceObjectiveStatus = "unverified-source-field" }
quests[27709] = { id = 27709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", sourceObjective = "Complete the Sentinel's Game by connecting the two red statues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27711] = { id = 27711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller's initiate, Goldmine, has need of you.\n\nI think that they're ready for you to help them with whatever's down in that mine.", sourceObjective = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "{name}, glad you're back! Have I got something fun for us to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27712] = { id = 27712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller has a goblin initiate? Goldmine is his name? He has need of you.\n\nI think that they're ready for you to do their dirty work with whatever's down in that mine.", sourceObjective = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "{name}, glad you're back! Have I got something fun for us to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27713] = { id = 27713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came", description = "Deathwing made quite a mess when he passed through these parts.  If it weren't for me, he'd probably still be here, layin' waste to all the good people of the Badlands.\n\nWhat, you don't believe me?  Fine, let me tell you the whole story.", sourceObjective = "Listen to Theldurin's tale.", progress = "Are you going to listen or not?", completion = "Some story, huh?  Now you know why Deathwing hasn't come back here since.", sourceObjectiveStatus = "unverified-source-field" }
quests[27714] = { id = 27714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: The Real Story", description = "Not only was Theldurin's story wrong, it was boring, unimaginitive, and slow.\n\nI'll tell you how things really happened on that day.", sourceObjective = "Listen to Lucien Tosselwrench's version of the story.", progress = "I'm not done with my story yet.  Sit back down.", completion = "The end!  No moral.", sourceObjectiveStatus = "unverified-source-field" }
quests[27715] = { id = 27715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: What Really Happened", description = "These two have no idea how to tell a story.  Theldurin's story was too short, and Lucien's tale was a little too tall, if you catch my drift.\n\nAlso, neither of their stories had action and fans admiring my awesomeness in them.\n\nSit back, {name}.  I'll tell you what really happened that day.", sourceObjective = "Listen to Martek the Exiled's version of the story.", progress = "I seem to have lost my place... let's see... where was I...", completion = "I can't believe those guys would interrupt me like that.  My story was going so well, too...\n\nAnyhow, thanks for sticking around so long.  It's nice to have someone new to share tall tales with.  I'm sure Lucien and Theldurin feel the same way.\n\nYou have any you'd like to share with us?", sourceObjectiveStatus = "unverified-source-field" }
quests[27716] = { id = 27716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Levia Dreamwaker, back with the Nespirah survivors, was looking for something exactly like this.>", sourceObjective = "Bring the Ancient Elven Etching to Levia Dreamwalker. You should find her with the Alliance Nespirah Survivors.", progress = "Hah! Did you see the admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! It will take me a while to translate, but this is precisely the kind of find I was hoping for.\n\nThere's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. Here... perhaps I have something that may be of use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27717] = { id = 27717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Elendri Goldenbrow, back with the Nespirah survivors, was looking for something exactly like this.>", sourceObjective = "Bring the Ancient Elven Etching to Elendri Goldenbrow. You should find her with the Horde Nespirah Survivors.", progress = "Hah! Did you see the captain giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! I can't have expected much more with the tools I gave you.\n\nI should be able to fill in the blanks and get this all written out shortly. There's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. You're not bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27718] = { id = 27718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Vashj'ir!", description = "All able-bodied members of the Horde are hereby ordered to report to Commander Thorak at Bladefist Bay in Durotar.\n\nNow, more than ever, your help is needed in battling our most hated enemy, the Alliance!\n\nTo reach Bladefist Bay you must travel south through the main gates of Orgrimmar and enter Durotar. From there, follow the path east to the coast. Thorak will be standing at his post near the docks.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to Commander Thorak at Bladefist Bay in Durotar.", completion = "Lok'tar, brother! You have arrived just in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27719] = { id = 27719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen, take your information and be gone from my demesne.", sourceObjective = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[27720] = { id = 27720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", sourceObjective = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[27721] = { id = 27721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Mount Hyjal!", description = "All able-bodied members of the Horde are hereby ordered to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Blackhoof to gain entry into Moonglade. Blackhoof is located at the tauren district in the Valley of Wisdom in Orgrimmar.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", progress = "Blackhoof sent you?", completion = "We knew the Horde would send help and not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27722] = { id = 27722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Deepholm!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Krogar at the Western Earthshrine in Orgrimmar.\n\nThe Earthen Ring, lead by our former Warchief, Thrall, requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world!\n\nThe Western Earthshrine can be found just north of the Valley of Wisdom.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Speak with Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27724] = { id = 27724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Vashj'ir!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Recruiter Burns in Stormwind Harbor.\n\nRecent attacks by the Horde on our trade ships must be met with swift and just force!\n\nStormwind Harbor can be found in the northwest region of Stormwind City.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship.", sourceObjectiveStatus = "unverified-source-field" }
quests[27725] = { id = 27725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quel'Danil Lodge", description = "I may appear far from home to you, {class}, but quite a few of my people were led here by Ambassador Rualeth. We have settled with the high elves of the Quel'Danil Lodge, to the northwest, to train in the ways of the Light and enjoy the peaceful beauty of this land.\n\nSuch peace may be short lived. We have seen the Horde moving further west from here. Could you travel to Quel'Danil and give warning to Anchorite Traska? Her cabin is just north of the main lodge.", sourceObjective = "Speak with Anchorite Traska at the Quel'Danil Lodge.", completion = "Yoro sends warning of the Horde? The Highvale have been cautious of an attack for some time now. In fact, we have been--\n\n<Screams and the clash of metal break out to the south.>\n\nBy the light... they are here!", sourceObjectiveStatus = "unverified-source-field" }
quests[27726] = { id = 27726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade.", completion = "We knew the Alliance would send help and not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27727] = { id = 27727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Deepholm!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.\n\nThe Earthen Ring requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world and destroy all life on Azeroth!\n\nThe Eastern Earthshrine can be found directly northwest of Stormwind Keep.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak with Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27729] = { id = 27729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, With Eeling", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", sourceObjective = "Kill 8 of any Eel in the Kelp Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27733] = { id = 27733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Ol' Switcheroo", description = "Look, I'd love to give the order and have my men blast these rebels to bits right now, but I can't because the entire Stockade is under Warden Thelwater's jurisdiction, and he only wants to contain them right now.\n\nRather than disobey orders, we're going to take care of this in a slightly different manner! We've managed to befriend Mortimer Moloch, who just so happens to be the ruthless rebel leader Randolph Moloch's twin. Kill Randolph, and we'll switch 'em so Mortimer can stop the rebellion peacefully!", sourceObjective = "Kill Randolph Moloch.", completion = "Yes, Mortimer just faked his own death. He'll probably take on his brother's name and continue on his 'epic schemes'. We'll just have to deal with that when the time comes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27737] = { id = 27737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Fire Be Saved!", description = "I'm well-versed in first aid and other forms of healing, and with the help of my Lightwell I've been able to nurse many of our men back to full health. The problem we still have is that it's so cold and damp down here that I'm losing them anyways, despite healing their wounds!\n\nThe quakes angered the elements that reside in the prison...when they erupted out of the earth they slaughtered half of the prisoners. If you slay their leader, Lord Overheat, and bring me his core I can use it to warm our men!", sourceObjective = "Obtain Lord Overheat's Fiery Core.", progress = "Do you have the core? Our men are dying in here!", completion = "Thank goodness! With this fire, our men will live through this ordeal!\n\nThank you so much, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[27738] = { id = 27738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Scales", description = "A spot on the southern end of the map was marked with hieroglyphs of crocodiles fighting each other.\n\nThat must be where Caimas took Tahet.\n\nGo to the Pit of Scales and find a way to rescue the Vizier's son.", sourceObjective = "Rescue Tahet at the Pit of Scales in Uldum.", progress = "{name}?", completion = "I thank you for what you've done, {name}.  You can count on my vote when High Council convenes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27739] = { id = 27739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnoll King", description = "{name}, I'm afraid I must ask of you the impossible.\n\nI received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here.\n\nDoing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces.\n\nYou must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.", sourceObjective = "Defeat Hogger.", progress = "Have you defeated Hogger?", completion = "You have performed a deed this day unlike any I have seen in my long career. Hogger's death will plague the Riverpaw for years to come, and hopefully put an end to their attacks on our people.\n\nGreatest of heroes, please take this as a sign of my eternal gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[27740] = { id = 27740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baba Bogbrew", description = "Hey, while you were out, the Baron stopped by! He kicked me until money came out!\n\nHe always does that though. But this time he asked me to tell you something! He wants you to go south and help out our herbalist, Baba Bogbrew.\n\nShe's all the way across the water! But just talk to my girl Daisy outside and she'll send you there the Crazy Larry way!", sourceObjective = "Talk to Lil' Crazy Daisy to take a cannon ride to Baba Bogbrew.", completion = "Ah, it's so nice to have help dropped in.\n\nModern convenience... I can't get enough of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27742] = { id = 27742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little on the Side", description = "You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff!\n\nWhat a waste!\n\nSo, what do you say? 90/10 my way?", sourceObjective = "Collect 6 Elementium Shards.", progress = "How much do you think you can carry?", completion = "<Goldmine slyly looks at the pile of Elementium shards.>\n\nHmm, I don't think that stuff's going to sell for much. I better give you your cut right now so you don't feel ripped off.", sourceObjectiveStatus = "unverified-source-field" }
quests[27743] = { id = 27743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While We're Here", description = "You know, while we're here, we might as well take care of the Twilight's Hammer intruders. This place used to be ours, after all!\n\nI'd help, but with my totems and weapons broken, I'm pretty helpless.", sourceObjective = "Slay 12 Twilight's Hammer cultists, either Depths Overseer or Twilight Miners, within the Elementium Depths.", progress = "Let's take care of a few more of them, okay?", completion = "They had it coming to them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27744] = { id = 27744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Ruination", description = "Examining the Twilight Rune of Earth, you can almost feel its power extending further into the Elementium Depths.\n\nIt's probably connected to other runes. Initiate Goldmine thinks that you should destroy all of them.", sourceObjective = "Destroy the Twilight Rune of Earth, Rune of Water, Rune of Air, and Rune of Fire.", progress = "We still have some runes to destroy, {name}.", completion = "That'll teach 'em to move in on our territory!\n\nWhat's that over across the way?", sourceObjectiveStatus = "unverified-source-field" }
quests[27745] = { id = 27745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fiery Reunion", description = "That's Magmatooth, my estranged fire elemental. {name}, you gotta kill him or he's gonna kill me!\n\nIt was all just a big misunderstanding. How was I to know he'd be mad about me \"borrowing\" his heart down in Deepholm? He can't die... not permanently anyway!\n\nHe's got the controller to the portal on him for sure. You gotta get the controller and then use it in the Fire portal to take us back to the entrance.", sourceObjective = "Obtain the Fire Portal Controller and use it at the Fire Portal.", progress = "{name}!", completion = "We survived and all of the portals are now shutdown!\n\nYou don't think Magmatooth is going to hold a grudge, do you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27746] = { id = 27746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empire of Dirt", description = "This war has taken its toll on us as a people. We have lost much to secure our place as the rightful rulers of Lordaeron. And though the moment is won, the battle continues to rage in other parts of the Eastern Kingdoms.\n\nI must return to the Undercity to recuperate. I want you to go to Hillsbrad Foothills in my stead, {name}. As my most trusted soldier, you will lead our forces to absolute domination against our enemies in Hillsbrad.\n\nReport to High Executor Darthalia at Southpoint Blockade, to the east.", sourceObjective = "Report to High Executor Darthalia at Southpoint Blockade in Hillsbrad Foothills.", completion = "News of your conquest in Silverpine emboldens us, {name}. We are prepared to fight at your command and beat back the last remaining vestiges of humanity in Hillsbrad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27747] = { id = 27747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total War", description = "Many of the Wildhammer have already fled their homes. It is time to wipe them from the map.\n\nUp on the ridge to the north you will find abandoned houses in the Thundermar Ruins. Kegs of potent Thundermar ale have been left behind.\n\nThundermar ale is 220 proof; I don't know how that's possible.\n\nSmash open the kegs and set their content aflame. Burn them out! Leave the dwarves nothing to return to!", sourceObjective = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27748] = { id = 27748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortune and Glory", description = "We have to keep moving, {name}. It's just a matter of time before those troops get their act together.\n\nThe coffer should be just beyond these ruins.\n\nStay on your toes. Something tells me this isn't over yet...", sourceObjective = "Kill the Obsidian Colossus.", completion = "Good to see you're still in one piece, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27750] = { id = 27750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Forage", description = "<Griff's stomach growls.>\n\nWhenever we Dragonmaw go on the warpath, everyone stops hunting.\n\nThe best tasting food is stolen from the mouths of the enemy. Up on the ridge north of the river there's a bunch of wrecked Wildhammer houses. I bet they're loaded with food.\n\nBring some to my mouth.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Hungry.", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! Did you get any for yourself?", sourceObjectiveStatus = "unverified-source-field" }
quests[27751] = { id = 27751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Wildhammer", description = "Since my people first claimed the Highlands, the Wildhammer dwarves have been our persistent foe. We fought them in Grim Batol, we fought them in the Wetlands, and even now open warfare rages to our north, across the river, amidst the Thundermar Ruins.\n\nProve your valor to me. Seek out and crush Wildhammer Warbrands. The best among them carry insignias - my warriors collect them by the dozen.\n\nCan you?", sourceObjective = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, {class}.", completion = "<Narkrall clenches the insignias in his weathered hand.>\n\nSo, {class}. There's more to you than meets the eye.\n\nMaybe your Horde can stand with the best of my warriors. Let's try you out...", sourceObjectiveStatus = "unverified-source-field" }
quests[27752] = { id = 27752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Like a Wildhammer", description = "S'not a boast to say that we Thundermars brew the finest ale in the Eastern Kingdoms. It's 220 proof. Yeah, you heard me!\n\nAs folks fled from the south to the town center, they were forced to leave behind their ale.\n\n<Blundy pauses, allowing the gravity of the situation to soak in.>\n\nGET IT BACK! That stuff'll turn even the stringiest of warriors into a whirlin' dervish of mouth-foaming destruction. Get them kegs! S'our only hope!", sourceObjective = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Careful - it's got some kick!", progress = "Get me that ale, {name}.\n\nHey, you haven't been skimmin' off the top, have you?", completion = "Oh aye ... we get a few of these kegs out to the boys on the front and we're gonna see some fireworks. Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27753] = { id = 27753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Leave a Dinner Behind", description = "Supplies are short, {name}. We've got refugees coming into Thundermar from up and down the ridge - that's a lot of mouths to feed.\n\nPlenty of food stores were left behind as people pulled their families to safety. We need that food!\n\nScour the Thundermar ruins south, east, and southwest of here for food stores.\n\nCareful, {class}! The fighting around the ruins is pretty intense.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Got some eats?", completion = "It's good - hardly a worm or weevil to be found!\n\nThis is a lifesaver to the folk who fled here for survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[27754] = { id = 27754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Takedown", description = "The Dragonmaw!\n\n<Colin spits.>\n\nMonsters, all of them. We've fought them up and down these highlands since the last war. And now they're joining forces with the Horde?\n\nIf you're going to convince us Wildhammers to unite under the Alliance banner, you'd best prove yourself against the Dragonmaw. Wade into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear. Then we'll talk.", sourceObjective = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "How goes the fight, {class}?", completion = "Look at that! That's quite a collection of trophies you have there.\n\nI'll spread the word. If a single Alliance {class} can do this, imagine what the rest of your lot can accomplish!", sourceObjectiveStatus = "unverified-source-field" }
quests[27755] = { id = 27755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of the Tombs", description = "The Neferset are not the only threat to our sacred tombs.\n\nA gnomish expedition stumbled upon our lands a few weeks ago.\n\nThey did not heed our warnings and dug too deep within a cursed vault.\n\nTheir entire expedition is now afflicted by a terrible curse that has robbed them of their sanity and taken control of their minds.\n\nThey now seek access to the deepest vaults of Uldum and pose a great threat. \n\nGo to the Sunstone Terrace and put their wretched souls out of their misery.", sourceObjective = "Slay 6 Crazed Diggers and Mekgineer Mixeltweed.", progress = "Is it done, {name}?  The expedition members cannot be saved.", completion = "They couldn't be saved, {name}.  The ancient curse that fell upon them is irrevocable.", sourceObjectiveStatus = "unverified-source-field" }
quests[27756] = { id = 27756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foreman", description = "If we're to find out what's going on down here it looks like we're going to have to fight our way through the entire Deadmines! Glubtok the Foreman will be the first major foe you encounter, a powerful ogre magi. Be careful, he possesses the brute strength of his race backed by his wicked spellcasting!\n\nTake this communicator so that I can keep in touch with you as we continue our investigation. Be careful down there.", sourceObjective = "Kill Glubtok.", completion = "<Bzzzzzzzzzzzzt.>\n\nNicely done! A clean kill. Now continue on and see what else you can find! We'll crack this case wide open with you on our side, I just know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27757] = { id = 27757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkest Depths", description = "I've been seeing sea creatures acting oddly through the whole swamp. The murlocs, yes, but before that the gilblins, and the makrura... I even saw some naga wander ashore the other day.\n\nSomething's calling them here, and working them into a frenzy to boot. Many of the creatures have been drawn to Stagalbog Cavern to the west. Something's down there, and if it gets any stronger we'll all start wandering in there too...\n\nYou should put a stop to whatever it is before that happens.", sourceObjective = "Slay Hr'nglth the Lost.", completion = "Oh my. It sounds like you ran across quite a sinister being. I wonder what one of those was doing all the way out here...", sourceObjectiveStatus = "unverified-source-field" }
quests[27758] = { id = 27758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Carpenter", description = "<Bzzzzzzzzzzzzt.>\n\nHello, can you hear me? Excellent!\n\nIt looks like Helix is in charge of building an enormous mast. You don't think they're trying to finish the Defias Juggernaut, do you?\n\nYou'd better go investigate {name}, and don't be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let's face it, it's probably going to be necessary.", sourceObjective = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nHey, it's Horatio. That was intense! I'm watching your progress on the Stormwind Communicator's Spyatron X3 application.\n\nThey sure are using a lot of heavily fortified doors to hide their work. Keep pushing forward and see what you find next. I bet it'll be a huge clue!", sourceObjectiveStatus = "unverified-source-field" }
quests[27760] = { id = 27760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artificial Intelligence", description = "<A feminine voice addresses you over the portable terminal.>\n\nEmergency code: 55-729.\n\nUpper cerebral cortex functions in expedition members have been compromised.\n\nPlease report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.", sourceObjective = "Speak to the A.I.D.A. terminal at the Surveyor's Outpost  in Uldum.", progress = "<The terminal whirrs as its mechanisms become active.>", completion = "Scanning subject...\n\nCerebral cortex diagnostics indicate the absence of \"tomb curse\" phenomenon.\n\nDiagnostics did reveal frequent head trauma.  The user would do well to exercise more caution around blunt objects in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[27761] = { id = 27761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disarming Distraction", description = "The curse has taken over the expedition members' higher brain functions, but my calculations reveal their suppressed adolescent subconscious can still be stimulated by realistic imagery.\n\nUtilize this holo-projector to distract them.\n\nThey are currently setting up explosives at the tomb to the east to attempt to gain access to secret passages in Uldum.\n\nThey seek dangerous re-origination technology beneath Uldum and must be stopped.", sourceObjective = "Disarm the First, Second and Third Bomb Clusters and deactivate 4 Unstable Bomb Bots at the Tomb of the Sun King.", progress = "Greetings, user {name}.  I am happy to see you are still unaffected by the effects of the expedition curse.", completion = "Well done, {name}.  The expedition has already doomed itself.\n\nThere is no need for it to endanger the rest of the world as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27762] = { id = 27762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuselight, Ho!", description = "Hey, {race}, listen up.  I got a job opportunity that you aren't gonna want to miss out on.\n\nWe been sent up here from Fuselight, a new goblin town way down in the Badlands.  Lots of money to be had down there, yes <sir/ma'am>.  And not nearly so many zombies... or uptight Argent paladin-types.\n\nNope, it's an untamed wilderness down there, and we're looking for someone like you to help us tame it.  Whenever you're ready... we'll be waiting.", sourceObjective = "Ride The Uncrashable to the Badlands, then report to Eddie Flofizzle.", completion = "Nice landing!", sourceObjectiveStatus = "unverified-source-field" }
quests[27763] = { id = 27763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fuselight Proper", description = "This, {race}, is paradise.  I've always wanted to live in a nice quiet town by the sea so I can focus on my explosions without any distractions.\n\nQuiet's not for everybody, though... 'specially the adventuring hero-type, like yourself.\n\nWe've installed a teleporter in the backside of town that'll take you up to the top of the cliffs.  From there, you can take the quick ride west into Fuselight proper, within the Badlands.\n\nThere should be more for you to do up there.  Tell 'em that Flo sent you.", sourceObjective = "Use the Teleporter in the back of Fuselight-by-the-Sea to port up the mountain, then report to Dolph Blastus at Fuselight in the Badlands.", completion = "Welcome to Fuselight!", sourceObjectiveStatus = "unverified-source-field" }
quests[27764] = { id = 27764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Request", description = "On to other matters.  I have a package that I need delivered.\n\nA young lady came by our town not long ago, looking for compressed blasting powder, a tempered mithril bomb casing, and some safety goggles.  Naturally, we had plenty of blasting powder and bomb casings to sell her, but the safety goggles were a little harder to find.\n\nLong story short, I've got the goggles, but she's already returned to her studies down in Lethlor Ravine.  Will you bring these down to her?", sourceObjective = "Bring Dolph's Package to Rhea at Lethlor Ravine in the Badlands.", progress = "Ahh... you've found me.  Good.", completion = "Thank you, {race}.  You may keep the goggles, as they have already served their purpose: they brought you to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27765] = { id = 27765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Sample: Wild Eggs", description = "I am experimenting with black dragons.  Specifically, I am interested in how they procreate.\n\nMy current experiments require plenty of black dragon eggs, which is why I am here in Lethlor Ravine.  I'd gather the eggs myself, but I think you'll benefit from helping me out.\n\nYou will find them along the edges of the ravine.  Beware the guardians that circle above - they do not appreciate stolen eggs.", sourceObjective = "Obtain 6 Wild Black Dragon Eggs.", progress = "Have you brought the eggs?", completion = "Thank you for gathering these so quickly, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27766] = { id = 27766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sample: Whelps", description = "I need another favor from you.  I need you to obtain the bodies of the black dragon whelplings that fly nearby.  Slay them, and bring the corpses to me.", sourceObjective = "Obtain 10 Scalding Whelp Corpses.", progress = "Have you done as I asked?", completion = "This grisly task was necessary, {name}.\n\nAll will be revealed to you soon.  For now, know this:\n\nI am no ordinary goblin.\n\nI serve a mistress of unimaginable power, and her motives here are not as dark as they might seem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27768] = { id = 27768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Two: The Bloodletter", description = "The trolls here perpetuate the fall of my brethren to the nightmare. They infect and corrupt green dragons with the blood of their foul god, and then harvest the evil that has grown within them. They are being farmed like livestock...\n\nThis disgusting savagery cannot continue. Return to where you left the Hall of Masks and take the other corridor towards the Butchery. Gomora the Bloodletter harvests corpses for these foul and evil rituals there. Take his undeserved life from him!", sourceObjective = "Slay Gomora the Bloodletter in the Butchery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27769] = { id = 27769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhea Revealed", description = "As I hinted earlier, I am no ordinary goblin.  You may have already guessed my true identity.\n\nAllow me to show you my true form.  As you have proven yourself trustworthy, I will also share with you the details of my plan.", sourceObjective = "Learn Rhea's true identity.", progress = "You are certainly impatient, {name}.", completion = "My true name is Rheastrasza, and I am an envoy of Alexstrasza herself, the Aspect of the red dragonflight.\n\nWith Deathwing currently occupied with other matters, we are going to find a way to redeem the black dragonflight.\n\nAnd you are going to help us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27770] = { id = 27770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Veil", description = "The black dragonflight was once noble.  They were the earth warders, protecting the very land itself.  How ironic that they would become the worst menace the land has known.\n\nI believe that there remains a sliver of hope, however, and so does my mistress.  The black dragonflight will live beyond Deathwing's treachery, and will soar as the noble earth warders once again.\n\nI wish to show you something.  Close your eyes, and I will reveal to you the final part of my studies.", sourceObjective = "Witness the final piece of Rhea's studies.", completion = "We will find a shred of good within these dragons, {name}.  Whether it is in the wild eggs you found, the bodies of the whelplings you slew, or the eggs that we have encouraged Nyxondra to lay... we will find an untainted black dragon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27771] = { id = 27771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Sample: Implanted Eggs", description = "Nyxondra is being held against her will.  She is hidden from her brood, right in the middle of their breeding grounds.  She lays eggs, but they will be taken away before she can see them hatch.\n\nCruel?  Perhaps... but not nearly as cruel as the treatment that their dragonflight showed my mistress.\n\nShow me that I can trust you, {name}.  Take Nyxondra's eggs, and bring them here.  You will need to beat Nyxondra into submission before you can take them.", sourceObjective = "Obtain 3 of Nyxondra's Eggs.", progress = "Remember, {name}... this is for the good of the black dragonflight.  We are here to redeem them, not to hurt them.  This is but a step in their recovery.", completion = "You have done everything that I have asked you, without question.  Our job here in Lethlor Ravine is done.\n\nIt is now time that I revealed everything to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27772] = { id = 27772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venerable Doctor Blam", description = "I made a calculated decision in revealing my identity to you, {name}.  I needed you to trust me, but I can no longer stay here in Lethlor Ravine, as my cover has quite clearly been blown.\n\nYou may be able to slip away unnoticed, however.  Here, take the results of our research, and bring them west.  At Agmond's End, you will find a gnome who knows what to do with these samples.\n\nHurry, {name}!  You mustn't loiter here any longer than necessary!", sourceObjective = "Bring the Black Dragon Samples to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Dr. H. Blam, at your service.  How can I be of assistance to you today?", completion = "Ooh!  Science stuff!  Let's see what you've got here...\n\nWild eggs?  Blech.  Useless.  These are never any good.\n\nOoooh, what's this?  Some sort of... pre-engineered egg?  This looks promising, but I don't want to know what Rhea had to do to get it.\n\nHmm... yes, some very nice corpses.  Very nice indeed.\n\nAlright, I'll see what I can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27773] = { id = 27773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Three: Prophet", description = "All that yet stands between me and the temple is Prophet Jammal'an himself. He is the leader of the Atal'ai trolls here, a foul manipulator.\n\nKnow that you do not face a mere crazed troll, {name}, but an instrument of forces beyond your darkest comprehension. Yet you do not fight alone; my strength and the will of the Green Dragonflight go with you.\n\nProceed to the Den of the Caller, left through the Hall of Ritual, and then down into the Hall of Bones. At the bottom, you will find Jammal'an.", sourceObjective = "Defeat Jammal'an the Prophet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27774] = { id = 27774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easily Swayed", description = "The most immediate threat to Fuselight is, without argument, the colony of ogres to the northwest.\n\nMost of our ogre neighbors used to be warrior-types, but it seems that more and more of them are practicing magic.  I won't have an army of ogre-magi at my doorstep.\n\nGo take out some of those Dustbelcher ogres.  Hopefully they'll get the picture and avoid messing with the might of Fuselight.", sourceObjective = "Slay 9 Dustbelcher ogres at Camp Kosh.", progress = "I'll feel much better when those ogres are gone.", completion = "I wonder where all of these ogre-magi are coming from?  Curious times, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27775] = { id = 27775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When the Going Gets Tough, Cheat", description = "I just can't get my invention to work!  Gah!\n\nThat's it, I've decided.  I'm going to cheat and use magic.\n\nWhat my invention really needs is a solid piston that's thin enough to fit through a narrow copper tube, but strong enough to withstand repeated impact without breaking.  The magical rods carried by those ogre magi to the north should work perfectly.\n\nFrom what I can tell, only the instructors carry the strong staves.", sourceObjective = "Obtain an Instructor's Rod from an Ogre-Mage Instructor at Camp Kosh.", progress = "I don't like to stoop to using magic on my inventions, but this is somewhat of an emergency.", completion = "A perfect fit!  My goat puncher is finally finished!", sourceObjectiveStatus = "unverified-source-field" }
quests[27776] = { id = 27776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Goat Time, Baby", description = "We have a little bit of a goat problem here in Fuselight, in case you haven't noticed.  They'll eat anything, and they seem to have taken a liking to the piles of cogs and gears that we tend to leave sitting around.\n\nIt's getting really annoying!\n\nYou'll find most of the billy goats wandering around the edge of town, near the cliff's edge.  Use this device on them to give 'em a little \"nudge\".", sourceObjective = "Use Garyanne's Goat Puncher on 12 Billy Goats in Fuselight.", completion = "Well done!  I have no doubt that those goats will be back, but they'll think twice before they nibble my cogs again!", sourceObjectiveStatus = "unverified-source-field" }
quests[27777] = { id = 27777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Access Codes", description = "The expedition's numbers are extremely large, user {name}.\n\nDealing with them by conventional means would take you an estimated 2,700,136.5 hours.\n\nWe can make use of a powerful source of energy held within expedition's crawler vehicle.\n\nWe will need the fusion core's access codes to accomplish this.\n\nMekgineer Twizzleflux has these codes and can be found at the Starwatch Tower to the southeast.\n\nI've uploaded jamming frequencies to a scrambler.  Use it to temporarily disable Twizzleflux's defenses.", sourceObjective = "Obtain the Core Access Codes from Twizzleflux the Insane.", progress = "Did you succeed, {name}?  I estimated your chances of survival at 68.5%.", completion = "Excellent job, user {name}.  We must obtain access to the fusion core now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27778] = { id = 27778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Wibson", description = "It is true.  New expedition crews have arrived by sea.\n\nMy scanners detect that they already have been afflicted by the curse phenomenon.\n\nYou must hurry and go aboard the M.A.C. Diver.  The access codes will give us control over the fusion core's functions, but there is still a layer of security we must bypass.\n\nUser {name}, I must ask you to hack a very sophisticated mainframe known as the \"Wibson.\"\n\nDo not worry I will provide you with further instructions.", sourceObjective = "Hack the Wibson Mainframe on top of the M.A.C. Diver.", progress = "Greetings, user {name}.", completion = "I am in control, user {name}.  But I cannot keep the core temperature stable indefinitely.", sourceObjectiveStatus = "unverified-source-field" }
quests[27779] = { id = 27779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomebliteration", description = "I have downloaded my program to the fusion core and have complete control over it.\n\nI've created a small pocket of air inside to avoid vaporizing user {name}.\n\nI will yield control of all movement functions so I can dedicate my cycles to keeping the core stable.\n\nGo down the hill and neutralize as many of the expedition members as possible.\n\nMy analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers.\n\nUser {name}, you must be assured that expedition members are without hope.", sourceObjective = "Obliterate 1000 Crazed Gnomes.", progress = "The expedition members' demise is unfortunate.", completion = "It is done, user {name}.  I thank you for your assistance with this unfortunate task.", sourceObjectiveStatus = "unverified-source-field" }
quests[27781] = { id = 27781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Machination", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHe-hello? {name}, are you there? Are you still alive? Hello?\n\nOh good, you're still there! What in the name of Lordareon are they building? It's some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! \n\nThrow out the rules, do whatever you have to do to thwart them!", sourceObjective = "Destroy the Foe Reaper 5000.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nYou're nearing the heart of their domain. There will likely be an extremely fortified door protecting the inner sanctum of the entire Defias operation. See if you can find anything that might pry it open!\n\nI suggest a stealthy method!", sourceObjectiveStatus = "unverified-source-field" }
quests[27782] = { id = 27782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Mathias says he needs you.\n\nHe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", sourceObjective = "Speak with Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. We know where Cho'gall's ultimate weapon is located!", sourceObjectiveStatus = "unverified-source-field" }
quests[27783] = { id = 27783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Garona says she needs you.\n\nShe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", sourceObjective = "Speak with Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. It's about time. We know where Cho'gall's ultimate weapon is located!", sourceObjectiveStatus = "unverified-source-field" }
quests[27784] = { id = 27784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\nMany SI:7 died to bring us this information.", sourceObjective = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", sourceObjectiveStatus = "unverified-source-field" }
quests[27785] = { id = 27785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral", description = "<Bzzzzzzzzzzzzt.>\n\nI can't believe it...they're almost done rebuilding it! We don't have much time, {name}.\n\nAdmiral Ripsnarl, Vanessa's right hand man, is bound to be on board. We'll never get to her if he's still alive to do anything about it. You're going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa's private quarters on the top deck.\n\nBe careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!", sourceObjective = "Kill Admiral Ripsnarl.", completion = "<Bzzzzzzzzzzzzt.>\n\nYour exploits have gained quite the following in the intelligence community, {name}. Many top members of SI:7 have been earnestly watching you infiltrate the Deadmines through their own Stormwind Communicators.\n\nMathias Shaw himself wants to speak with you! I'll transfer you over momentarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[27786] = { id = 27786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\n<Garona begins sharpening her blades.>\n\nMany Kor'kron died to bring us this information.", sourceObjective = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", sourceObjectiveStatus = "unverified-source-field" }
quests[27787] = { id = 27787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", sourceObjective = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, lad! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27788] = { id = 27788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", sourceObjective = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, {name}! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27789] = { id = 27789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggish Troubles", description = "I'll need some time to analyze these samples, as well as a break from this trogg-shooting duty.  Go man one of my turrets and take out as many troggs as you can.  I'll be here studying.\n\nThe turrets have two abilities: a regular shot, as well as an electrical overload, for when too many enemies get close!  Heh, heh.  Good luck.\n\nOh, and look out for the big, slow troggs.  You probably don't want to let them anywhere near you.", sourceObjective = "Enter a Blam Turret, then survive four waves of trogg attacks.", progress = "Not quite done yet.  Need some more time.", completion = "The results are in.  I've identified traces of corruption in all three samples you brought me.  Rhea will be quite disappointed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27790] = { id = 27790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "Hello there, {name}. I've heard a great deal about you. Listen closely, you're only going to have one solid shot at this.\n\nThe new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized.\n\nI'm shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we're in luck.", sourceObjective = "Kill the Defias Kingpin.", completion = "You very well may have saved all of Stormwind with your efforts here today, {name}. Vanessa may still be out there, but she is an insignificant threat now that the Juggernaut will be placed under our careful watch. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27791] = { id = 27791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dustwind Dig", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Explorers' League has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to Lead Prospector Durdin at the camp to the north.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", sourceObjective = "Speak with Lead Prospector Durdin at Dustwind Dig in the Badlands.", completion = "Titans?  You wanna know about titans?\n\nYou came to the right place, lad.  We're on the brink of somethin' big.", sourceObjectiveStatus = "unverified-source-field" }
quests[27792] = { id = 27792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Fair in Love, War, and Archaeology", description = "First things first, though.  I'm not just going to sit here and tell you everything we've discovered down in those ruins.  We've got problems to take care of!\n\nMost pressing is those upstart Reliquary hooligans, just on the other side of the tomb.  They're makin' off with all of our loot!  Don't they know that diggin's dwarf work?\n\nHunt down a few of their \"excavators\" - more like bandits, if you ask me - and bring some of these precious artifacts back to me.\n\nTHEN we'll talk titans.", sourceObjective = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "Your bags look heavy.  Heavy with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nAlright, fine.  Let's talk titans, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27793] = { id = 27793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", sourceObjective = "Investigate The Warden and The Sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27794] = { id = 27794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", sourceObjective = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27795] = { id = 27795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "The battle's proceeding just the way I wanted it. With their warriors nearly exhausted, I've sent in our cavalry.\n\nWhat I wasn't expecting was ogres. Our knights are well matched against the brutes, but they're going to need help.\n\nI need you back on the field right away, {name}. Few can bring down an ogre on foot, but I think I can count on you. Don't disappoint me.", sourceObjective = "Slay 6 Stonard Ogres.", completion = "Going toe to toe with ogres is impressive, {name}. I'm glad I've got soldiers like you out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27796] = { id = 27796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "Once those Reliquary honks got here, we panicked, and we all just started looting indiscriminately.\n\nA lot of bad archaeology happened that day.\n\nLuckily, Olga happened upon this small jade statue.  We thought it to be a key of some sort, but can't figure out what it opens.  Maybe you'll have some better luck with it.", sourceObjective = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27797] = { id = 27797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We very nearly had this statue stolen from us by one of Bloodwatcher's Reliquary stooges.  We managed to catch him in the act, and we've retrieved the statue, but it hasn't really paid off.\n\nIt appears to be a key of some sort, but I can't find the lock anywhere inside those ruins.  You feel like giving it a try?", sourceObjective = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue slides into place on the cold marble slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27798] = { id = 27798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen take your information and be gone from my demesne.", sourceObjective = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[27803] = { id = 27803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome Relief", description = "I've got boys formin' defensive lines on all sides of the town, keepin' back the elementals streaming from the torn ground. They're good lads and they've been holdin' firm, but even the sturdiest dwarf tires eventually.\n\nThey're split into shifts: one hour of rest for every hour on the line. Best I can get'm with the men we have.\n\nIf you want to be helpin', pick a line and take up a shift. Give some of my boys a welcome breather. Report back in once you've killed several of the elementals.", sourceObjective = "Kill 8 Subjugated Firestarters.", progress = "Don't be dallyin'. These men are pourin' every fiber of their bein' into holding this town, and I'll not see them insulted by the presence of anyone that won't hold their weight.", completion = "Good work, boy. Good to have another capable set of hands about.", sourceObjectiveStatus = "unverified-source-field" }
quests[27804] = { id = 27804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Homes We Have", description = "We've already been pushed back farther than I'd hoped, but I'm not about to give up our homes to these mongrels. They may burn them, pillage them, and spit on the rubbled remains, but we'll still fight to take them back.\n\nThat being said, I rather like them not burnt. I have the boys running buckets from the well to try to keep the fire down. If you'd join them, they can help out by tossing you buckets so you don't have to make the runs.", sourceObjective = "Extinguish 50 fires at Firebeard's Patrol.", progress = "As long as we work together, we can overcome anything the Twilight's Hammer might throw at us.", completion = "Thanks for your help. Every little bit makes a difference.\n\nWe'll keep the water going until we can push the Twilight back.", sourceObjectiveStatus = "unverified-source-field" }
quests[27805] = { id = 27805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Comforts", description = "You're the new face that's meant to be helping Keegan out I take it? Pleasure to meet you. Maybe you can lend a favor or two more to the troubled Wildhammer that have made refuge here.\n\nWe were all forced to retreat to this building quickly, and some of us left behind things of great value in our destroyed homes nearby. Would you mind bringing them back after you go out there? You would bring happiness to some very troubled souls.", sourceObjective = "Find and return Meara's Dried Roses, Parlan's Ivory Hammer, and Aprika's Doll.", progress = "Were you able to find their valuables? I know it seems so minor, but little things make a big difference to some people in times like these.", completion = "You are very generous. Thank you.\n\nThere's a lot of darkness in our world these days. We appreciate the light that you've brought here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27806] = { id = 27806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorable Bearing", description = "Iain, my second in command, bore the body of one of our fallen heroes to the cathedral to the west. He's the man I've put in charge of reforming a wing of gryphon riders from whatever scattered forces he can find. I would like you to help him.\n\nI should impress upon you the urgency of this task. We will not be able to hold here forever; the Twilight's Hammer or the Dragonmaw orcs will eventually overwhelm us. Putting together an active gryphon wing may be our only hope for surviving these conflicts.", sourceObjective = "Speak to Iain Firebeard at the Firebeard Cemetery.", completion = "Greetings, {race}. Sent by Keegan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27807] = { id = 27807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Mullan", description = "If we're going to pull a full gryphon wing back together, we're going to need to move fast to gather the survivors before they leave or get picked off. I've got a bead on a few groups of riders that stuck together. I'm leavin' to find the Thundermar riders and the Moore riders shortly.\n\nThe Mullans were heading up west to the Crucible of Carnage last I saw. Go see if you can convince Duglas Mullan to join up with Keegan - he should owe him a favor or three.", sourceObjective = "Speak to Duglas Mullan at the Crucible of Carnage.", completion = "Iain sent ya?\n\nYou don't look like a Firebeard to me. Why exactly should I be listenin' to anything you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[27808] = { id = 27808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn as a Doyle", description = "The Doyle riders were last spotted convergin' in the trees to the south, on the border of the Obsidian Forest. They're a stubborn bunch and are likely to take some convincin' if they're going to join up with us.\n\nYour best bet with Keeland Doyle is to tell'm Cailin Longfellow's taken up shelter with us back at the town. Keeland's got a good soft spot for her and she just might be enough to convince him to drag all his boys along.", sourceObjective = "Speak to Keeland Doyle in the Highland Forest.", completion = "It seems the Doyles suffered the worst of the attacking Twilight drakes.\n\nIt's clear that they fought to the end: not a single rider's footprint more than a few yards from his gryphon. It's doubtful there were any survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27809] = { id = 27809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard Bellows", description = "I also need ya to seek out Mackay and his men on the other side of the Devouring Breach, at the Gorshak War Camp.\n\nThe Dragonmaw didn't survive the initial onslaught, and Mackay's lookin' to ransack what he can of their camp to supply our fight. There shouldn't be much convincin' necessary, but they'll likely want a hand wrappin' things up there before they make their way back to Keegan.\n\nGive'm a boot in the arse from ol' Iain if ya have to.", sourceObjective = "Speak to Mackay Firebeard at the Gorshak War Camp.", completion = "'Bout that time, eh? Help us wrap things up then.", sourceObjectiveStatus = "unverified-source-field" }
quests[27810] = { id = 27810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fighting Spirit", description = "Keegan wants the Mullans to take wing with'm eh? If there's a dwarf I'd fly for, he'd be it. Still, I don't get why he'd be sendin' an outsider to be recruitin' me - not right polite by my standards.\n\nI'm guessin' ya don't last 20 seconds with any of my boys, at the bar or in the battlefield. Prove me wrong. Take one of'm down in a fight and then I'll think about flyin' with ol' Keegan.", sourceObjective = "Challenge and defeat one of the Mullan Gryphon Riders.", progress = "Naw, I'll not be fightin' ya. Get in there and challenge one of my boys if you've got a gut on ya at all.", completion = "That's the stuff! Not half bad. You've got a bit of fight in ya after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27811] = { id = 27811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Battle", description = "Don't let Duglas fool you, the Mullans have been itchin' to take wing again, and if there's anyone we'd do it for, it's Firebeard.\n\nWe left our gryphons in the Highland Forest to the south to hunt and to get away from the sounds of battle for a bit. They deserved a rest.\n\nIf you want us back in the air soon, you'd do well to help us bring our gryphons back in.\n\nTake this piece of charred highland birch. We use it during training - as soon as they smell it, they'll come straight back to us.", sourceObjective = "Find 8 Mullan Gryphons and dispatch them back to their gryphon riders.", progress = "We're not going to be much use to you without our birds.", completion = "Good on you. I always feel like a part of me is missing when my gryphon isn't nearby. I can't speak for Duglas or the rest of the clan, but I'll be ready to ride at Firebeard's call.", sourceObjectiveStatus = "unverified-source-field" }
quests[27812] = { id = 27812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loyalty of Clan Mullan", description = "Your point's made. Keegan can count on us. We'll meet'm back at town as soon as all the boys are rallied up.\n\nYou're tough for not bein' a Wildhammer. Guess they breed'm good where you come from too.\n\nStill, haven't seen ya drink yet. That'll be the real test.", sourceObjective = "Return the news on Clan Mullan to Iain Firebeard at the Firebeard Cemetery.", completion = "Ya got the Mullans. Good news! They're worth more than their weight in a fight, and they ain't exactly skinny.", sourceObjectiveStatus = "unverified-source-field" }
quests[27813] = { id = 27813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Worthy of a Dragonmaw", description = "The Twilight sacked this town, killin' most of the Dragonmaw that lived in it. A few survived though, and they're not right keen on us takin' liberties with their supplies.\n\nNot that that matters much.\n\nWell, I'm not right keen on them attackin' my boys. Kill'm off, chase'm out - I don't care, just get'm gone.", sourceObjective = "Defeat 6 Dragonmaw Stragglers.", progress = "Clear this place out for me yet? Not lookin' like it.", completion = "That's more like it. Let's finish gatherin' up supplies and get back to Keegan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27814] = { id = 27814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything We Can Get", description = "Stay back and forge more weapons?  Pah!  A Forgehammer has ne'er been afraid of battle!  Who needs the safety of home to make weapons?  Besides - there is oodles of raw material out here.  Those Dragonmaw weapons are worthless, but they can be smelted down to make actual weapons.  Bring me 8 Dragonmaw weapons so me daughter and I can forge real weapons out of them.", sourceObjective = "Bring 8 Dragonmaw weapons to Brom Forgehammer at Gorshak War Camp.", progress = "How many have you got so far?", completion = "Yer a good lad.  Have me thanks and a little gold for yer troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27815] = { id = 27815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somethin' for the Boys", description = "Cleaned up the camp and ran errands for Forgehammer?  Not bad for a wee {class}.  Take these to Iain at Firebeard Cemetery, and he should reward you for a job well done.", sourceObjective = "Bring Forgehammer's weapons to Iain Firebeard at the Firebeard Cemetery.", progress = "What have we here?", completion = "Hah! Looks like their raid went mighty well then. I'll have to buy ol' Forgehammer a round once we finish with this mess.", sourceObjectiveStatus = "unverified-source-field" }
quests[27816] = { id = 27816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Request", description = "Shame about the Doyles. It's a fair miracle that as many of us made it out as is though, so can't count it as much of a surprise.\n\nThose louts at Thundermar are cowards. Even after tellin' them it was Keegan askin', they won't set foot outside of their town. I did rope in the Moores though, so that's at least three clans' worth.\n\nKeegan wanted to hear from ya personally when you returned. Go find'm in town.", sourceObjective = "Speak to Keegan Firebeard at Firebeard's Patrol.", completion = "It seems you had some luck bringin' riders back. Well timed too - we just pushed the elementals back, so we should have the arm room to lead an attack right away.\n\nThank you, {name}. You're a good {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27817] = { id = 27817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping the Hammer", description = "Thanks to you and Iain, we've got enough riders together that we can take the fight back to the Twilight.\n\nWe're trained to fight while ridin', but a second rider to handle the Stormhammer tends to be more efficient. I thought you might enjoy the honor.\n\nPick your gryphon and join the fight. Best be quick about it though - we're aimin' to clear every last one of those Twilight off of those floatin' rocks before the hour's out.", sourceObjective = "Kill 12 Twilight Stormbenders and Servias Windterror using one of the gryphons at Firebeard's Patrol.", progress = "Today is the day that the tables turn.", completion = "Now that's how it's done, lad!\n\nWith a real gryphon wing back together, we can take the fight to the rest of the Twilight. You're welcome to fly with us anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27818] = { id = 27818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Signs", description = "I settled here well before Bogpaddle was founded, to brew my potions and find some peace and quiet. I know this swamp like the back of my old, gnarly hand.\n\nThere's been a change in the wildlife recently. Those winged snakes you may have seen in the stagalbog are wind serpents, and they haven't been seen around here for ages.\n\nThey're also prime for ingredients if they're the kind I'm thinking of. Be a dear and gather me some of their hearts, will you?", sourceObjective = "Collect 5 Intact Stagalbog Serpent Hearts.", progress = "Don't be squeamish now.", completion = "Let's have a look then...\n\nMmm, oh dear. That's what I thought these were. They might still be usable, but it's horrid to have such things in my backyard.", sourceObjectiveStatus = "unverified-source-field" }
quests[27819] = { id = 27819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST - RVM" }
quests[27821] = { id = 27821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "With war raging across the entire world, the last thing we need is a Horde settlement right in our backyard. Redridge, Duskwood, even Elwynn itself are all a day's march from here.\n\nWe've made the first strike, and I don't plan to give the Horde a chance to catch their breath. So consider yourself deployed. Grab a weapon, join the rest of the troops out in the Bloodmire, and start killing orcs.\n\nReport back here after you've done some damage. I want you back alive...and that's an order. Dismissed!", sourceObjective = "Slay 8 Stonard Warriors.", completion = "More black on you than red... that's what I like to see. Looks like you've got what it takes, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27822] = { id = 27822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "I want victory to be totally assured here. Having more resources isn't enough; we need to make sure the enemy has nothing.\n\nStonard's forces depend on the lumber gathered from the surrounding woods. The orcish peons that chop the lumber may not be warriors, but they still know nothing but hate for humans.\n\nShow no mercy. I want those peons killed and the supply of lumber to Stonard cut off completely.", sourceObjective = "Slay 5 Stonard Peons.", completion = "We've had strikes on our own lumber line while you've been gone. This should at least put us on equal footing for gathering rates.\n\nGood work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27823] = { id = 27823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dwarf's Got Needs", description = "I can appreciate a good diggin' as much as any other dwarf, don't get me wrong.  It's just that... well, we do so much diggin', and so little drinkin', that sometimes I wonder if I should just hang up me shovel and head back to Ironforge.\n\nBut not today.  I've got some diggin' in me yet.\n\nThose Dark Iron dwarves at Hammertoe's Digsite - just north of here - make some powerful fine beer, right here in the desert.  You think you could pick up a few for me?", sourceObjective = "Obtain 15 mugs of Shadowstout.", progress = "<Sigrun licks his lips in anticipation.>", completion = "<Sigrun instantly downs a dusty mug of shadowstout.>\n\nWow, this stuff is strong!  I knew they had beer, but I never expected them to have shadowstout!  That's my favorite shadowbeer!", sourceObjectiveStatus = "unverified-source-field" }
quests[27824] = { id = 27824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Stuff", description = "I've got a little proposition for you, if you're interested.\n\nThose Dark Irons were here before Durdin and his crew arrived.  That means that, once these titan ruins opened up, the dark irons were the first ones in there, lootin' all the good stuff.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nYou've more than proven your ability to wallop a dwarf.  Head on into that fortress and wallop your way to titan treasure.\n\nI'd go with, but I'm drunk.", sourceObjective = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "Now here's some treasure!  I was beginning to worry that these weren't titan ruins at all!\n\nI'll show these to Durdin.  Thanks again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27825] = { id = 27825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on what would be our hunting grounds, we have no way to get food.\n\nThe ogres to our southwest, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", sourceObjective = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27826] = { id = 27826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dragon's Mouth", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get this back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover pretty well when she transformed into her true form in front of all those whelps.  She's now in the west, staying at an Alliance camp called Dragon's Mouth.\n\nShe'll be waiting for you.  And for that egg.", sourceObjective = "Bring the Purified Black Dragon Egg to Rhea at Dragon's Mouth in the Badlands.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27827] = { id = 27827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swift, the Fierce, and the Stout", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nTalk to Eric, over on the other side of camp.  He and his brothers will be joining you.", sourceObjective = "Speak with Eric \"The Swift\" at Dragon's Mouth in the Badlands.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", sourceObjectiveStatus = "unverified-source-field" }
quests[27828] = { id = 27828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric, the Utility Dwarf", description = "Before we get too crazy what with the dragon-killin', let me tell you a little bit about how I fight.\n\n\"The Swift\" is what they call me, and here's why: I'll dash straight into your enemies - helmet first, mind you - and stun 'em for a few seconds.  I also keep a few potions with me for tight spots.\n\nWhy don't we practice fightin' together?  Head out into the field, and try out my abilities.", sourceObjective = "Use Eric's Charge and Eric's Pocket Potion.", progress = "We're not through yet, {name}.", completion = "I'm not what you'd call \"very strong\" or \"battle-hardened\", but I get the job done my own way.\n\nLookin' forward to fightin' with you.  I never fought with a fancy-lookin' {class} before.", sourceObjectiveStatus = "unverified-source-field" }
quests[27829] = { id = 27829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, northeast of Dragon's Mouth.  Hunt him down and defeat him.  You will likely need the help of your new dwarven allies.", sourceObjective = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!", sourceObjectiveStatus = "unverified-source-field" }
quests[27830] = { id = 27830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  It appears that they've taken over a large portion of New Kargath, the large Horde settlement northwest of Dragon's Mouth.  Their troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.\n\nWe dragons do not take part in the squabbles between Horde and Alliance, but I do understand the risk you take in entering New Kargath.  Please, heroes... be careful.", sourceObjective = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27831] = { id = 27831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", sourceObjective = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", sourceObjectiveStatus = "unverified-source-field" }
quests[27832] = { id = 27832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", sourceObjective = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27833] = { id = 27833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "I'd say we have a dragon problem, but it seems like they're a little more interested in New Kargath then they are in our small encampment.  Nevertheless, I've got top men focused on keeping the dragons at bay.\n\nOne problem that has gone unchecked, however, is the ogre camp to our southwest.  A small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier.  Thin their ranks before they thin ours.", sourceObjective = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "Thank you, {race}.  However, I'm afraid I don't have much to give you, other than this passionate round of applause.\n\n\n\nOh, I do have these.  Here, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[27834] = { id = 27834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baelog, the Glass Cannon", description = "Before I start droppin' arrows on those dragons, I'd better introduce myself.\n\nI'm Baelog, the muscle of this group.  My sword bites like a crocolisk, and my arrows sing like banshees.  I tend to wear down quickly, however, and can't take as much punishment as either of my two brothers.\n\nYou give the word, and I'll send an aimed shot right through your target's heart.  I can also cheer my brothers on, sending 'em into a battle-fueled frenzy.\n\nWhy don't we go try fighting together?", sourceObjective = "Use Baelog's Valhalla Shot and Baelog's Warcry.", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, {name}.  You're getting the hang of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27835] = { id = 27835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olaf, the Big Fella'", description = "You may not have noticed, but I'm pretty big, as far as dwarves go.\n\nI make sure that my two brothers here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", sourceObjective = "Use Olaf's Shield Wall and Olaf's Mighty Shout.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Olaf is around.  Just let me know, and I'll protect you from the monsters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27836] = { id = 27836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Spread", description = "Slaying the foul creatures that plague the river will not be enough, {name}.\n\nA new generation of these monstrosities already threatens to spawn within our holy waters.\n\nSeek their foul eggs and destroy them.", sourceObjective = "Destroy 6 Slitherer Eggs.", progress = "Have you succeeded, {name}?", completion = "I thank you, {name}.  This will make our prophetic visions that much clearer.", sourceObjectiveStatus = "unverified-source-field" }
